(window.STORIES=window.STORIES||[]).push(...[{"n": 41, "l": "اللينك دا ف اول 100 حلقه | من قصص السيره النبويه وتكملة قصص الأنبياء وقصص القرآن | #السيره_النبويه | الجزء الأول | قبل مولد رسول الله | ١ | أصحاب الأخدود | ١ | والجزء الثاني | قبل مولد رسول الله | ٢ | أصحاب الأخدود | ٢", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية_\n#الحلقة_الأولى\n#قبل_مولد_رسول_الله_الجزء_الأول\n#أصحاب_الأخدود_الجزء_الأول\nإن شاء الله هنبدأ النهاردة الجزء الأول من السيرة النبوية،\nالسلسلة دي تكملة لقصص الأنبياء،\nولأن السيرة النبوية هي قصة خاتم الأنبياء والمرسلين فهي طويلة وفيها تفاصيل كثيرة فخليتها في سلسلة لوحدها،\nوطبعا هيدخل معانا قصص القرآن،\nيعني هنحكي قصص القرآن واحنا بنحكي السيرة؛ لأن القصص دي لها أسباب نزول فلما نوصل للأحداث بتاعتها هنقولها إن شاء الله\nفي نقطة لازم أوضحها قبل ما نبدأ وهي إن السيرة دي مش حكاية بنسمعها ..السيرة النبوية دي دين\nرسول الله ﷺ قال :\n \" أَلَا إِنِّي أُوتِيتُ الْقُرْآنَ وَمِثْلَهُ مَعَهُ\"\nيعني ربنا أنزل القرآن إللي هو الوحي الأول وكمان أنزل وحي ثاني وهو السنة أو خلينا نقول السيرة،\nيعني قصة حياة رسول الله ﷺ إللي بتشرح القرآن وتوضح معناه\n \nفاحنا لما نقرأ السيرة تبقى نيتنا طلب العلم لأننا بنتعلم ديننا...بنتعلم القرآن والسنة إللي فيهم كوووول أحكام الإسلام\nوالإيمان لا يكتمل إلا بحب رسول الله ﷺ ،\nومش أي حب\nده حبه لازم يكون مُقدّم على كل حب في حياتنا،\nقال رسول الله ﷺ:\n\"لا يؤمن أحدكم حتى أكون أحَب إليه من والده وولده والناس أجمعين\"\nفإزاي هنحب حد للدرجة دي واحنا منعرفش عنه أي حاجة \nيعني إننا نتعلم سيرة رسول الله ﷺ ده مش حاجة اختيارية ده فرض علينا\nعارفين ليه؟\nلأن هي الطريقة الوحيدة لفهم القرآن وأحكامه،\nده غير إننا عندنا امتحان مكون من ثلاثة أسئلة لازم نجاوب \nعليهم ..لو مجاوبناش على الأسئلة دي هنتعذب في النار\nالأسئلة هي : مَن ربك..مَن نبيك ..ما دينك؟\nاحنا سهل جدا نجاوب عليها دلوقتي لكن في القبر غييير\nهنجاوب إزاي على مَن ربك واحنا منعرفش أي حاجة عنه؟\nولّا مَن نبيك واحنا منعرفش سنته ولا حياته ولا بنعمل زيه؟\nهنجاوب إزاي على ما دينك واحنا منعرفش عن الدين إلا حاجات متفرقة من هنا وهنا\nفاعملوا حسابكم إنكم بتتعلموا دينكم \nطبعا هعتمد على الأحاديث الصحيحة فقط إن شاء الله، \nوأنا بشرح ولو في أحاديث ضعيفة مشهورة بين الناس هقول لكم يا جماعة خدوا بالكم الحديث ده ضعيف...\nزي حديث الحمامة إللي باضت والعنكبوت إللي عمل خيوط على باب الغار لما رسول الله ﷺ كان مهاجر واختبأ فيه...الحديث ده ضعيف مع إنه مشهور بين الناس\nوإن شاء الله هنربط السيرة بالواقع بتاعنا عشان نقدر نخليها منهج نقدر نطبقه في حياتنا ونتشبه برسول الله ﷺ عشان ربنا يحشرنا معاه\n \nقبل ما ندخل في تفاصيل السيرة عايزين نعرف الأول إيه إللي حصل بعد رفع عيسى عليه السلام وإزاي النصرانية انتشرت مع إن اتباع عيسى عليه السلام كانوا قليلين\n☆ممكن حد يسأل طيب وده إيه علاقته بالسيرة \nبكل بساطة لسببين: \n◇الأول:\nإن في أحداث حصلت مذكورة في القرآن وقبل ما يُولد رسول الله بسنين طويلة زي قصة أصحاب الأخدود\nوكمان قصة أصحاب الفيل.\n◇الثاني: \nعشان نعرف الأرض كانت عاملة إزاي في الوقت ده،\nونشوف كمية الكفر والفجور إللي كان على وجه الأرض لدرجة إن رسول الله ﷺ  قال:\n\"إن الله نَظر إلى أهل الأرض فمَقَتَهم عربهم وعجمهم إلا بقايا من أهل الكتاب\". 《صحيح مسلم》\nوالمَقت معناه شدة الكراهية...يعني ربنا نظر لأهل الأرض قبل البعثة النبوية فكرههم لشدة كفرهم وطغيانهم في الأرض،\nفطبعا لازم نعرف الأرض كانت عاملة إزاي،\nعشان نشوف الفرق إللي هيحصل لما رسول الله ﷺ يُبعث بالرسالة،\nوهل احنا عندنا أمل إن حال الأمة يتصلح ونقدر نرجع الناس للدين تاني ولّا لأ\nهنرجع للوقت إللي رُفع فيه عيسى عليه السلام،\nبعد رفع عيسى عليه السلام تفرّق الحواريين وبقوا يدعوا الناس للنصرانية،\nوكان لهم أتباع ولكن اليهود مكنوش بيسيبوهم، كانوا بيحرّضوا الملوك عليهم ،\nوإن الناس دي هيخربوا ملكك فكانت الملوك بتعذب من يتبع الحواريين فكانوا بيؤمنوا في السر،\nوالحواريين نفسهم اتعرضوا للتعذيب الشديد جدا،\nفهربوا لأماكن مختلفة من العالم وبدأوا ينشروا النصرانية بين الناس،\nومع مرور الوقت تعرضت النصرانية لتحريفات كثيرة،\nلأن الإنجيل لم يُكتب هو كمان زي ما التوراة لم تُكتب قبل كده،\nوكانوا بيعلّموا بعض النصرانية عن طريق رسائل بيبعتوها لبعض،\nوبعد مائتين سنة من رفع عيسى عليه السلام كتبوا أناجيل كثيرة جدا،\nوطبعا فيها تحريف كبير جدا\nوقالوا إن عيسى ابن الله وكلام كتير كده مش موضوعنا\nفالنصارى بدأوا يتفرّقوا في الأرض ويعبدوا ربنا منعزلين عن الناس ،\n《راجعوا سلسلة خط الزمن لدكتور راغب السرجاني》\nوكان في ناس قليلة جدا جدا هي إللي استمرت على دين عيسى عليه السلام الأصلي بدون أي تحريف\nوكان في برده أحبار يعني علماء من اليهود بيسافروا من مكان لمكان عشان ينشروا اليهودية ويعرّفوا الناس الدين،\nفي اليمن كان في ملك اسمه رَبِيعة بن نَصر،\nشاف رؤيا فجمع الكُهّان والسحرة ففسروا له الرؤيا بإن الأحباش يعني أهل الحبشة هيحكموا اليمن،\nفخاف على أهله وذريته فأرسلهم للعراق يقعدوا هناك،\nوهو استمر يحكم اليمن ومات ربيعة بن نصر وجاء بعده أبناؤه حكموا اليمن،\nوكان من أبناؤه إللي حكموا واحد اسمه أسعد ولقبه تُبَّع وكان مُشرك وكان بيسافر للتجارة،\nففي مرة وهو مسافر عدّى على يثرب وساب ابنه فيها للتجارة،\n فاختلف ابنه مع أهل يثرب فقتلوه، فرجع لهم تُبّع عشان يقاتلهم ويخرّب يثرب،\nفلما وصل وحاصرهم طلع له اثنين من أحبار اليهود وقالوا له إنه مش هيقدر يخرّب يثرب عشان البلد دي هيهاجر لها نبي في المستقبل،\nفقال لهم وإنتم عرفتم منين \nفقالوا عندنا في التوراة مكتوب الكلام ده\n\"أَوَلَمْ يَكُن لَّهُمْ آيَةً أَن يَعْلَمَهُ عُلَمَاءُ بَنِي إِسْرَائِيلَ\"\nفسألهم يعني إيه توراة؛ لأنه كان مشرك وميعرفش حاجة عن الأديان، فشرحوا له التوحيد فعجبه الموضوع ودخل في اليهودية\nوأخذ تُبّع معاه الرجلين دول من أحبار اليهود عشان يعلموا أهل اليمن اليهودية،\nوهم ماشيين مرّوا على مكة فكان عايز يهدم الكعبة فأحبار اليهود إللي كانوا معاه قالوا له: متعملش كده ..ربنا هيهلكك لأن مفيش على ظهر الأرض بيت لله غير ده،\nلكن طُوف به وعظّمه،\nفكان تُبّع ده أول واحد كَسى الكعبة، الكعبة كانت حجر عاري كده من غير أي حاجة لحد ما كساها تُبّع ملك اليمن،\nولما وصل لليمن بدأ يدعو قومه لليهودية فآمن معه معظم الناس،\nوبعد ما مات تُبّع الناس كفروا فربنا عاقبهم وأهلكهم.\n\"أَهُمْ خَيْرٌ أَمْ قَوْمُ تُبَّعٍ وَالَّذِينَ مِن قَبْلِهِمْ ۚ أَهْلَكْنَاهُمْ ۖ إِنَّهُمْ كَانُوا مُجْرِمِينَ\"\nمرت السنين بعد بعثة عيسى عليه السلام والناس من أهل اليمن كانوا متفرقين وكان في قاطع طريق ومعاه عصابة فوسط التفرّق ده جمع أكبر عدد من أفراد العصابة واستولى على الحكم ،\nوكان الرجل ده ظالم والناس كلها بتكرهه،\nفي واحد من سلالة تُبّع اسمه ذو نُوّاس تَسلّل للرجل الظالم ده وقتله واستعاد حكم اليمن تاني،\nفي نفس الوقت ده كان في راهب من رُهبان النصارى على التوحيد على دين عيسى عليه السلام كان مُهاجر من بلاد الشام طلع عليه قُطّاع طُرق أخذوه وباعوه في حتة اسمها نَجْرَان في شبه الجزيرة العربية،\nفكان بيشتغل عند سيده ويتعبد وقت فراغه،\nفدخل عليه سيده  في ليلة من الليالي لقى حواليه نور،\nوكان الراهب ده له كرامات،\nفالرجل سأل الراهب إنت إيه حكايتك ..فالراهب شرح له التوحيد ودين عيسى عليه السلام،\nفالرجل تردّد وكان عندهم شجرة بيعبدوها ، فالراهب قال للرجل لو إلهي أهلك إلهك تعبد إلهي \nفالرجل قال له ماشي \nفالراهب قال للرجل اجمع الناس ..فبدأ الراهب يصلي ويدعو لحد ما ربنا أنزل صاعقة من السماء وأحرقت الشجرة فدخل أهل نجران كلهم في النصرانية\n☆عايزاكم تركزوا في تسلسل الأحداث وتشوفوا إزاي إن ربنا لما يريد شيء بيهيء أسبابه\nفي بعض الرهبان من أهل نجران بدأوا يسافروا هنا وهناك عشان يدعوا لعبادة الله على دين عيسى عليه السلام،\nمن الرّهبان دول واحد راح لليمن عند الملك ذو نواس،\nفكان ذو نواس ده كافر وطبعا السحر والكهانة كان حاجة أساسية في تثبيت ملكه بين الناس،\nفكبير السحرة قال للملك ده: \nأنا كبرت في السن فشوف لي ولد صغير كده ذكي أعلمه السحر ويبقى خليفة من بعدي يساعدك،\nفلقوا غلام فعلا واضح عليه علامات الذكاء، وبدأ الساحر يعلمه أمور السحر،\nفي يوم من الأيام والغلام ماشي عدى على صومعة الراهب إللي جاء من نجران ده،\nواحنا قلنا قبل كده يعني إيه صومعة في قصة جريج\nفسمع الغلام صوت حد بيتكلم وبيدعي،\nفلقى رجل فسأله الغلام إنت بتعمل إيه هنا فقعد يشرح له التوحيد ودين عيسى عليه السلام،\nفالولد كان بيروح للساحر متأخر فكان بيضربه،\nولما كان بيرجع لأهله متأخر كانوا بيضربوه، فاشتكى للراهب فقال له قل للساحر أهلي إللي أخروني،\nوقل لأهلك الساحر هو إللي أخرني ومحدش هيعمل لك حاجة،\nمرت الأيام والغلام بيتعلم من الراهب والساحر،\nففي يوم وهو ماشي لقى الناس متجمعين ومش عارفين يكملوا طريقهم بسبب إن في دابة كبيرة سدت عليهم الطريق،\nحيوان كبير يعني ويُقال إنه كان أسد والله أعلم \nفالغلام قال: النهاردة أعرف الساحر أفضل ولّا الراهب أفضل\nفأخذ حجر من الأرض ودعا ربنا وقال: يارب لو أمر الراهب أحب إليك من أمر الساحر فاقتل الدابة دي ورمى الحجر على الدابة فقتلها\n \nوالناس شافت إللي حصل وكل واحد مشي في طريقه وهم بيتكلموا في إللي حصل،\nفالغلام راح للراهب وحكى له إللي حصل،\nفالراهب قال له: بص يابني إنت بقيت أحسن مني وربنا أجرى على إيدك المعجزات،\nفانت هتُبتلى ..لأن الإنسان يبتلى على قدر دينه،\nفلو ابتُليت متقولش لحد على مكاني ولا تقول إنك تعرفني\nوكان الغلام يُشفي الناس من البرص ويرجع للأعمى بصره ويشفي الناس من أمراض كثيرة ..طبعا كل ده بإذن الله،\nهي كرامات ربنا بيثبت بها قلب الغلام الصغير،\nفمين إللي سمع بموضوع الغلام إنه بيُشفي الأعمى\nواحد من جلساء الملك وكان أعمى،\nفراح للغلام البيت بتاعه وأخذ معاه أموال وكنوز كثيرة ودخل على الغلام وقال له:\nشوف كل الأموال والكنوز دي لك لو إنت شفيتني،\nفالغلام قال له : \nأنا مش بشفي حد..ربنا هو إللي بيشفي فلو إنت آمنت بالله أنا هدعو الله لك إنه يشفيك،\nفآمن جليس الملك وربنا رد عليه بصره، وراح يقعد مع الملك زي ما بيقعد معاه كل يوم،\nفالملك بص له واستغرب وسأله: من إللي رجّع لك بصرك\nفالرجل قال له: ربي\nفالملك قال له : وإنت عندك رب غيري\nفالرجل قال له: ربي وربك الله\nفالملك قعد يعذبه لحد ما دلّهم على الغلام \nفالملك عارف الغلام ..ده ساحر المستقبل \nفأمر الجنود إنهم يجيبوا الغلام، فلما جاء الغلام الملك قال له:\nإنت وصل من سحرك إنك تُشفي الأبرص وترجع للأعمى بصره وتعمل الحاجات دي كلها\nفالغلام قال له: أنا لا أشفي احد..ربنا هو إللي بيشفي\nفالملك قعد يعذب الغلام لحد ما دلّهم على الراهب\nفجابوا الراهب وقالوا له يا ترجع عن دينك يا إما هنقتلك،\nفقال لهم: مش هرجع عن ديني\nفجابوا منشار وبدأوا ينشروا الراهب من رأسه لحد ما سقط نصين أمام الغلام وأمام جليس الملك كنوع من الإرهاب والتخويف يعني عشان يرجعوا،\nفالملك قال لجليسه ترجع عن دينك ولا تُقتل زيه،\nفقال: مش هرجع عن ديني، فنُشر بالمنشار هو كمان\nمش باقي غير الغلام..الملك مش عايز يخسره وخصوصا إنه لسه صغير\nفالملك قال نهدده بالقتل يمكن يرجع،\nفأمر الجنود إنهم يأخذوا الغلام ويطلعوا على قمة جبل ويحاولوا يقنعوه إنه يرجع عن دينه،\nولو رفض خلاص اقتلوه..فلما طلعوا على قمة الجبل الجنود هددوا الغلام قالوا له: \nترجع عن دينك وتبقى مُقرب من الملك وخليفة الساحر ولك شأن بيننا ولا نرميك من الجبل ده\nيا ترى هل الغلام هيوافق إنه يرجع عن دينه ويعيش مُنعم في الدنيا ولا هيختار الموت؟\nده إللي هنعرفه الجزء الجاي إن شاء الله\n♡\n#قصص_الأنبياء(٢)\n#السيرة_النبوية_إيمان_شلبي\n#الحلقة_الثانية\n#قبل_مولد_رسول_الله_الجزء_الثاني\n#أصحاب_الأخدود_الجزء_الثاني\nوقفنا المرة إللي فاتت عند الغلام لما جنود الملك أخذوه وطلعوا بيه على قمة جبل وبدأوا يساومُوه،\nيعني يقولوا له يابني اعقل وهتبقى انت الساحر وهتبقى كلمتك مسموعة، ده غير النعيم إللي هتكون فيه،\nولو مسمعتش الكلام هنرميك من فوق الجبل..شوف الفرق بقى..يعني تبقى عايش مُنعّم ولا نموتك\nالغلام إللي لسه مبلغش حتى...يعني عمره أقل من خمسة عشرة سنة عمل إيه؟\nبكل هدوووء وثقة ويقين دعا ربنا وقال :\nاللهم اكفنيهم بما شئت\n☆أصل يا جماعة الموضوع منتهي بالنسبة له، هو عارف إنه على حق، هو مش كان دعا ربنا قبل كده إنه يخليه يشوف آية لو الراهب على حق يقتل الدابة \nوكانت النتيجة إن الجبل اتهز ووقعوا كلهم وماتوا ماعدا الغلام\nلكن الغلام عمل حاجة غريبة جدا\nالمفروض والطبيعي إنه يهرب بجلده ويبعد عن الملك وينقذ نفسه\nلكن الغلام رجع للملك تاني\nفلما دخل على الملك، سأله فين الجنود إللي كانوا معاك\nقال له الغلام : ربنا كفاني شرهم\nالملك بقى مش يتّعظ ولا حتى يفكر في إللي حصل ولا يسأل الغلام عن دينه\nلأ ..ده أمر جنود تانيين إنهم يأخذوا الغلام ويركبوا سفينة ويهددوه بالقتل ...يا إما يرجع عن دينه أو يقتلوه\nفلما ركبوا السفينة والجنود هدّدوا الغلام،\nالغلام برده دعا: اللهم اكفنيهم بما شئت\nفاتقلبت السفينة وماتوا كلهم ماعدا الغلام هو الوحيد إللي نجى\nمش يهرب بقى... ده رجع تاني للملك\n \nفالملك لما شافه سأله فين الجنود إللي كانوا معاك\nفالغلام قال له : ربنا نجاني منهم\nوقبل ما الملك يأمر جنود تانيين إنهم يقتلوا الغلام،\nالغلام قال له:\nشوف، انت مش هتقدر تقتلني إلا لو عملت إللي هقول لك عليه\nفالملك قال له: أعمل إيه\n☆الواحد مش عارف يتعجب من مين أكثر ..من الغلام إللي رجع عشان الملك يقتله،\nولّا من الملك إللي معندهوش ذرة عقل ومش بيفكر إلا في قتل الغلام ومش قادر يشوف قدرة ربنا ومعجزاته\nالمهم، الغلام قال له:\nاجمع الناس في مكان واحد واصلبني في جذع شجرة وبعدين خذ سهم من الأسهم إللي معايا و ضَعْه في القوس وقل بصوت عالي يسمعه الناس بسم الله رب الغلام وارمني بالسهم، \nلو عملت كده هتقدر تقتلني\nفالملك جمع الناس وعمل زي ما الغلام قال له بالضبط..وقال بسم الله رب الغلام ورمى السهم فنزل السهم في صُدْغِه فقتله،\nوطبعا الناس كانت عارفة إللي بيحصل مع الغلام وإزاي إن الملك مكنش قادر يقتله وإن الجنود هم إللي بيموتوا كل مرة  وإنه مقدرش يقتله إلا لما قال:\nبسم الله رب الغلام،\nفبعد ما قُتل الغلام الناس كلها في نفس واحد قالت: آمنا بالله رب الغلام\nوهو ده السبب إللي منع الغلام إنه يهرب\nعنده رسالة عايز يوصلها للملك وللناس\nالراهب إللي هو المُعلم الأول قُتل،\nومفيش غيره ينشر الدين فلو كان هرب مين إللي كان هينقذ الناس دي من ضلال الكفر والشرك\nيُقال إن الناس إللي آمنت في اللحظة دي عشرين ألف إنسان،\nيعني الملك ده لو كان ساب الغلام يدعو طول عمره مكنش هيؤمن العدد ده كله\nبس سبحان الله كل ما أراد إنسان إنه يحارب دين ربنا؛ حربه دي بتكون سبب في انتشار الدين أكثر \nوموت شخص واحد أهه كان سبب في إحياء قلوب الآلاف \n☆نقف هنا وقفة مهمة جدا \nطبعا احنا شايفين في واقعنا الأطفال إللي بتُقتل وتُذبح وبتموت من البرد والناس إللي بتُعتقل وبتُعذب وممكن تموت تحت التعذيب،\nالناس دي لها رسالة زي الغلام بالضبط...هم لمّا يُعذبوا أو يموتوا جزاؤهم الجنة إن شاء الله ونحسبهم شهداء،\nوربنا بيخفف عنهم ألم التعذيب وألم القتل،\nاحنا ممكن نتخيل إنهم بيتألموا ألم شديد جدا زي الراهب إللي نُشر بالمنشار نصفين،\nمتخيلين منشار بينشر جمجمة على الحي كده لحد ما يتقسم نصين \nالموضوع تخيله بس مرعب، فما بالنا باللي حصل معاه كده فعلا\nلكن دي من وجهة نظرنا احنا البشرية ،\nأما في حسابات ربنا فالموضوع مختلف تماما، رسول الله ﷺ  قال إن الشهيد مش بيحس بأي وجع إلا زي ماحنا بنحس بوجع القَرصة،\nفالعذاب والقتل بالنسبة لهم أجر وبالنسبة لنا إحياء لقلوبنا،\nلما نشوف طفل بيموت من البرد ولّا إنسان معتقل ولّا...ولّا...،\nقلوبنا القاسية بتلين وبنرفع إيدنا بالدعاء للناس دي،\nوبيخلينا نشكر نعمة ربنا إللي احنا فيها وغيرها وغيرها من الحكم التي لا يعلمها إلا الله،\nوفي نفس الوقت هو فتنة للناس إللي في قلوبها مرض ونفوسها خبيثة،\nعشان ربنا يطلع إللي جواهم عشان يُقيم عليهم الحُجة لما يقولوا هو فين ربنا ..وفين رحمة ربنا..وإزاي ربنا يقبل بالظلم ..وإزاي...وإزاي...\nوفي واحد من أكبر الملحدين دلوقتي وكان حافظ للقرآن في يوم من الأيام قال الكلام ده فعلا\nربنا مش بيقول لنا القصص من باب التسلية...القصص للعبرة.. لكن العبرة لمن يعتبر\nربنا حكيم رحيم ولا يرضى بالظلم لكن احنا إللي مش شايفين حكمة ربنا وبدل ما نتهم عقولنا بالعجز عن فهم حكمة ربنا، \nبنَتّهم ربنا بالظلم وعدم الرحمة والعياذ بالله \nأصحاب الملك لما شافوا الناس آمنت قالوا له حصل إللي كنت خايف منه\nكنت خايف من ثلاثة بس أهه الناس كلهم آمنوا \nفأمر الملك بحفر الأخاديد يعني حُفَر طويلة عميقة ويولّعوا فيها النار ويسأل الناس، إللي يصمم على إيمانه برب الغلام يرموه في النار،\nفقتل الملك ده ناس كثيرة جدا، \n\"قُتِلَ أَصْحَابُ الأُخْدُودِ\"\nويُقال إن المحرقة دي مكنتش في اليمن بس، ده حتى في نجران وفي أماكن تانية عشان يرد الناس عن دينهم\n\"إذْ هُمْ عَلَيْهَا قُعُودٌ\"\nالناس دي كان ذنبها بس إنها آمنت بالله، مطلبوش ملك ولا فلوس ولا أي حاجة، مجرد الإيمان بالله خلى الملك يقتلهم بالمنظر ده\n\"وَمَا نَقَمُوا مِنْهُمْ إِلاَّ أَن يُؤْمِنُوا بِاللَّهِ الْعَزِيزِ الْحَمِيدِ\"\nالمشهد مخلصش يا جماعة..في يوم قيامة..والناس إللي فتنت المؤمنين وعذبتهم دول ربنا هيعذبهم في نار جهنم،\nونار جهنم مش أي نار...ده نار الدنيا بتاعتنا دي جزء من سبعين جزء من نار جهنم\n\"إِنَّ الَّذِينَ فَتَنُوا الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ ثُمَّ لَمْ يَتُوبُوا فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ الْحَرِيقِ\"\nوالناس إللي اتعذبت وقُتلت دي جزاؤهم الجنة..والجنة دي غمسة واحدة فيها بتُنسي أبأَس أهل الأرض بُؤسه وشقاؤه فما بالكم باللي هيعيش خالد فيها أبدا\n\"إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الأَنْهَارُ ذَلِكَ الْفَوْزُ الْكَبِيرُ\"\n◇ملحوظة:\nالحديث بتاع المرأة إللي ابنها تكلم وهو رضيع وقال لها ترمي بنفسها في النار لأنها على الحق حديث ضعيف،\nوحتى لو كان صحيح فالرواية بتقول امرأة كان معها صبي،\nوالصبي هو الصغير إللي لسه بيرضع أو هو الطفل إللي لسه مبلغش،\nوده غير حديث لم يتكلم في المهد إلا ثلاثة وشرحناه قبل كده وهو حديث صحيح، \nوالكلام في المهد معناه إن الطفل بيكون عمره أيام.\n《هتلاقوا شرح الموضوع بالتفصيل في موقع الإسلام سؤال وجواب》\n☆شوفتم إزاي إذا أراد الله شيئا هيأ أسبابه\nفاكرين الراهب إللي قُطّاع الطرق أسروه وبعدين باعوه وبقى عبد،\nأكيد ساعتها هو كان زعلان إن حاجة زي كده حصلت،\nلكن شوفوا تقدير ربنا وحكمته...بسبب حادثة بسيطة زي كده،\nأهل نجران كلهم آمنوا بسببه وكمان أهل اليمن وحصلت قصة أصحاب الأخدود دي كلها بسببه وفي ميزان حسناته،\nولحد دلوقتي وإلى قيام الساعة هنفضل نحكي قصص الناس دي،\nفلما يحصل لك ابتلاء أو أي حاجة ظاهرها شر لك متزعلش وأبشر بالخير ..فرب الخير لا يأتي إلا بالخير\nمحدش نَجَى من المجزرة دي غير رجل اسمه دَوْس ذو ثَعلبان،\nاستطاع إنه يهرب لكن جنود الملك ذو نواس راحوا وراه عشان يمسكوه، فدخل في أرض رملية والجنود معرفوش يمسكوه،\nفقعد يفكر يعمل إيه عشان يثأر للناس إللي قُتلت ظُلم دي،\nففكر في قيصر ملك الروم وكان على النصرانية،\nفراح له دَوس ذو ثعلبان وحكى له إللي حصل فغضب جدا،\nلكن قال له اليمن بعيدة ومش هقدر أروح بجيشي هناك،\nلكن أنا هبعث معاك رسالة للنجاشي ملك الحبشة وهو يساعدك\n☆حكّام الروم بيُقال لهم قيصر وحكام الحبشة بيُقال لهم النجاشي، وحكام الفرس بيقال لهم كِسرى.\nفراح دَوس ذو ثعلبان للنجاشي ملك الحبشة في الوقت ده وهو غير النجاشي أصْحمة إللي هيكون في زمن رسول الله ﷺ وهنعرف قصته وقتها إن شاء الله،\nحكى دَوس ذو ثعلبان للنجاشي إللي حصل وغضب النجاشي جدا وكان على النصرانية هو كمان،\nفجهز جيش قوي كان حوالي سبعين ألف مقاتل بقيادة واحد اسمه أَرْياط،\nوكان في جيش أرياط واحد اسمه 《أَبْرهة》،\nوصل الجيش لليمن وحصل القتال وبدأ القتال بين ملك اليمن ذو نواس وجيشه وجيش أرياط،\nوانهزم ذو نواس وهرب للبحر في سفينة، فلما خاف إنهم يلحقوا به ويقتلوه انتحر \nوحكم الأحباش اليمن وكان الحاكم هو أرياط،\nفاكرين الرؤيا إللي شافها ربيعة بن نصر وكان تفسيرها إن الأحباش هيحكموا اليمن \n...أهه اتحققت\nأرياط ده كان ظالم جدا حتى كان بيظلم الأحباش إللي كانوا معاه،\nفالأحباش اشتكوا لأبرهة فجمعهم وجيش الحبشة بقى مُنقسم لقسمين ..قسم مع أرياط وقسم مع أبرهة،\nفأبرهة طلب إنه يتكلم مع أرياط قال له:\nدلوقتي لو احنا اتقاتلنا جيش الحبشة هيفنى وأهل اليمن هيرجعوا يحكموا تاتي،\nفخلينا أنا وأنت نتقاتل وإللي يغلب هو إللي يحكم \nفوافق أرياط وبدأ القتال بين الإثنين ،\nوهم بيتقاتلوا أرياط ضرب أبرهة على رأسه بالحربة فشقت حاجبه وأنفه وشفته ..وبقى اسمه أبرهة الأشْرم،\nلكن أبرهة استطاع إنه يتغلب على أرياط وقتله وبقى هو حاكم اليمن،\nوصل الكلام للنجاشي فغضب جدا...إزاي أبرهة يقتل القائد بتاعه فحلف إنه مش هيسيب أبرهة إلا لما يدوس أرض اليمن ويحلق شعره أبرهة،\nفأبرهة حلق شعره وأخذ شوية من تراب اليمن وحطها في جراب زي كيس كده وأرسله للنجاشي مع رسالة بيقول له:\nإن هو عبد له وإنه مش هيخالف أمره ،\nوإن القتال إللي حصل كان بسبب ظلم أرياط وإن هو أقوى من أرياط في حكم اليمن،\nوأنا حلقت لك شعري وبعثت لك تراب اليمن تدوس عليه عشان أبر حلفانك،\nفرضي النجاشي عنه وأقرّه على حكم اليمن،\nفأبرهة عشان يثبت ولاؤه للنجاشي بنى كنيسة عظيمة جدا محدش بنى زيها قبل كده أبدا،\nوسماها القُلَيْس وأمر الناس إنهم يحجوا لها،\nوبعث للنجاشي وقال له أنا بنيت لك كنيسة عظيمة وهخلي العرب يحجوا لها،\nفوصل الكلام ده لواحد من العرب من قبيلة كِنانة،\nفتسلل للكنيسة وتبرّز فيها يعني عمل فيها حمام إهانة لها ،\nفلما عرف أبرهة باللي حصل قال مين إللي عمل كده\nفقالوا له واحد من أهل البيت إللي العرب بتحج له بعد ما عرف إنك عايز تخليهم يحجوا للقليس\nفغضب أبرهة وحلف إنه هيروح ويهدم البيت ده،\nوبدأ يجهز جيشه عشان يروح مكة ويهدم البيت الذي يحج إليه العرب\n《البداية والنهاية لابن كثير》\n☆نقف هنا ثواني ونرجع بالزمن للوراء شوية حلوين كده\nكل كلامنا في قصص الأنبياء إللي فاتت من بعد إبراهيم عليه السلام كان في فرع يعقوب،\n إللي هو ابن إسحاق بن إبراهيم عليهم جميعا السلام يعني فرع بني إسرائيل،\nوكان الفرع ده موجود في خط فلسطين ومصر زي ما قلنا في شرح قصة يوسف وموسى عليهما السلام والأحداث إللي حصلت،\nاحنا بقى هنسيب الفرع ده ونأخذ فرع إسماعيل عليه السلام،\nاحنا طبعا عارفين إن إسماعيل عليه السلام كان سكن مكة مع أمه هاجر،\nوحصلت قصة زمزم وبعدين بناء الكعبة، واستقرار إسماعيل في مكة وزواجه من قبيلة جُرهم و...و..إلخ\nكل ده شرحناه في قصة إسماعيل عليه السلام فمش هنعيد تاني \n الجزيرة العربية في عهد إسماعيل عليه السلام وما بعده استمرت على التوحيد، يعني الناس كانت بتعبد ربنا سنين طويلة جدا على دين إبراهيم عليه السلام،\nلحد ما أتى رجل اسمه《 عمرو بن لُحَي》 وكان رئيس قبيلة خُزاعة، وكانت قبيلة قوية،\nفالقبيلة دي كانت عايزة تاخد الحكم من قبيلة جُرهم إللي هي أصلا موجودة من زمن إسماعيل عليه السلام،\nوحصل بينهم حرب فانتصرت قبيلة خزاعة بقيادة عمرو بن لُحَي،\nفقبيلة جُرهم حبت تنتقم من خزاعة وتعطّل عليهم عيشتهم في مكة راحوا دافنين بئر زمزم ومبقاش لها أي أثر\nوهربت قبيلة جُرهم من مكة إلا قليل منهم،\nفاضطرت قبيلة خزاعة إنهم يجيبوا الماء من خارج مكة\nعمرو بن لحي ده كان هو سيد مكة بلا مُنازع،\nوكان غني جدا وكريم جدا ومحدش يقدر يرفض أي أمر بيقوله،\nتقدروا تقولوا كلامه بالنسبة لهم كان زي الشرع كده لا يُرد \nفي مرة سافر عمر بن لُحي إلى الشام للتجارة، فكان في قبيلة اسمها العمَاليق وكانوا بيعبدوا الأصنام،\nفسألهم عمرو بن لُحي عن الأصنام دي لأن العرب كانوا على التوحيد على دين إبراهيم عليه السلام وميعرفوش يعني إيه أصنام ،\nفقالوا له: بيساعدونا إذا جُعنا وينصرونا ويسقونا الماء وبيقربونا إلى الله\nفعجبه الموضوع وقال لهم أعطوني واحد من الأصنام دي يمكن يعيننا لأننا معندناش مية \nفأعطوه صنم اسمه هُبَل، فكان أول صنم أُدخل في الجزيرة العربية\nوبدأ عمرو بن لحي يأمر الناس بعبادة هُبل فأطاعه الناس\nفكان هو أول من بدّل دين العرب \nومش بس كده ده عمل كوارث تانية ...\nهنعرفها إن شاء الله الجزء الجاي وهنعرف رسول الله ﷺ  قال إيه عن عمرو بن لحي\n☆باقي القصص هنا"}, {"n": 42, "l": "الجزء الثالث | قبل مولد رسول الله | ٣ | أصحاب الفيل | والجزء الرابع | إعادة حفر زمزم | ميلاد رسول الله", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثالثة\n#قبل_مولد_رسول_الله_الجزء_الثالث\n#أصحاب_الفيل\nكنا واقفين المرة إللي فاتت عند عمرو بن لُحَيّ لما سافر بلاد الشام وعجبه عبادة الأصنام فأتى بصنم وأدخله الجزيرة العربية وأمر الناس إنهم يعبدوا الصنم ده فالناس عبدوه فعلا،\nوكان العرب على التوحيد يعني بيعبدوا الله فكان هو مَن بدّل دين العرب\nوأدخل آلهة تانية غير هُبل وأمر كل قبيلة في مكة إن يكون لهم صنم عند الكعبة تعبده،\nوانتشرت الأصنام في مكة ومن أشهر الأصنام بعد هُبل اللات والعُزّى،\nوغيّر تلبية الحج..التلبية الصحيحة المعروفة : \nلبيك اللهم لبيك ..لبيك لا شريك لك لبيك..إن الحمد والنعمة لك والملك ..لا شريك لك.\nفراح مزوّد عليها:\n\"إلا شريكًا هو لك تملكه وما مَلك\"\nيعني معندكش شريك إلا شريك أنت تملكه،\nوبدأ يُشرّع الشرائع لأهل مكة ويخترع حاجات غريبة ،\nيعني سَن لهم سُنة الأنعام التي لا تُمس، عارفين الآية إللي بتقول:\n\"مَا جَعَلَ اللَّهُ مِن بَحِيرَةٍ وَلَا سَائِبَةٍ وَلَا وَصِيلَةٍ وَلَا حَامٍ ۙ وَلَٰكِنَّ الَّذِينَ كَفَرُوا يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ ۖ وَأَكْثَرُهُمْ لَا يَعْقِلُونَ \"\nالكفار كانوا بيقولوا إن ربنا هو إللي أمر بالحاجات دي فربنا رد عليهم بالقرآن إنه لا أوجبها ولا أمر بها ده عمرو بن لحي إللي هو شرّع الحاجات دي\nخلونا ناخدهم واحدة واحدة\n \n◇البَحِيرة يعني الناقة إللي ولدت خمس مرات يشقّوا أذنها ومحدش لا يركبها ولا يذبحها يسيبوها كده..بقت مقدسة\nأما السّائبة يعني واحد بينذِر نذر ..يقول يارب لو أنت شفيتني أو يارب لو فلان الغائب رجع أو...أو...فأنا هسيب الناقة بتاعتي دي ومش هركبها تاني.\n◇الوَصِيلة: يعني لو الشاة إللي هي المعزة ولدت ذكر ذبحوه للآلهة بتاعتهم ولو ولدت أنثى هم يأخذوها يذبحوها لنفسهم،\nولو ولدت ذكر وأنثى قالوا :وصلت أخاها فميذبحوش الذكر للآلهة.\n◇الحام يعني ذَكر الناقة لو اتولد بسببه عشرة ذكور؛ يحمِي ظهره يعني محدش يركبه ولا يُحمل عليه أي شيء ولو مات الرجال والنساء يأكلوه.\nفكل الحاجات إللي أمر بيها عمرو بن لُحَيّ،\nوالناس عادي تسمع كلامه وتنفذ ..مفيش أي مخ يفكروا بيه\nقال رسول الله ﷺ عن عمرو بن لُحي:\n\"رأيت عمرو بن لُحي يجر قُصُبَه في النار\" \nقُصُبه يعني أمعاؤه، يعني عمرو بن لُحَيّ في النار\nودي كانت قصة دخول الأصنام إلى مكة وإللي هنلاقيها بعدين في عهد رسول الله ﷺ \nنرجع بقى لأبرهة الحبشي إللي كان بنَى كنيسة وكان عايز العرب يحجّوا لها وجاء رجل من العرب من《 أهل النَّسِيء》وتبرّز في الكنيسة فحلف إنه هيهدم البيت إللي العرب بيحجوا له\n☆أهل النسيء دول كانوا بيعظموا الكعبة جدا وهمّ لهم قصة،\nعارفين الآية إللي بتقول :\n\"إِنَّمَا النَّسِيءُ زِيَادَةٌ فِي الْكُفْرِ ۖ \"\nكلمة النسيء معناها التأخير...احنا عارفين إن الأشهر الحُرم أربعة: رجب و ذو القعدة و ذو الحجة ومحرم،\n\"إِنَّ عِدَّةَ الشُّهُورِ عِندَ اللَّهِ اثْنَا عَشَرَ شَهْرًا فِي كِتَابِ اللَّهِ يَوْمَ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ مِنْهَا أَرْبَعَةٌ حُرُمٌ\"\nوالأشهر الحرم معناها إن مينفعش يكون فيها حرب والعرب أصلا عيشتهم على الحرب بينهم،\nففي ثلاثة شهور ورا بعض حُرم 《ذو القعدة و ذو الحجة  ومحرم》\nوده كده عامل لهم أزمة، يعملوا إيه\nفاختاروا مجموعة من الناس وسموهم أهل النّسِيء وقالوا الناس دي من حقهم يؤخروا الأشهر الحرم، \nيعني يؤخّروا محرم لصفر مثلا ،فيبدلوا شهر صفر مع شهر محرم،\nفيكون ذو القعدة حرام وذو الحجة حرام وبعدين ميجيش شهر محرم، لأ، يجي شهر صفر وبكده يطلعوا من الورطة \nفكانوا بيعملوا كده سنة وسنة..آخر لخبطة يعني\nوده تفسير آية :\n\"يُضَلُّ بِهِ الَّذِينَ كَفَرُوا يُحِلُّونَهُ عَامًا وَيُحَرِّمُونَهُ عَامًا لِّيُوَاطِئُوا عِدَّةَ مَا حَرَّمَ اللَّهُ فَيُحِلُّوا مَا حَرَّمَ اللَّهُ ۚ \"\nلكن الترتيب في الأشهر رجع زي ما كان تاني والأشهر فعلا مظبوطة دلوقتي\n♡شوفتوا إزاي إحنا لسه مدخلناش في شرح السيرة لكن عرفنا تفسير كم آية في القرآن\nجهّز أبرهة جيشه  لهدم الكعبة ،ودي تاني محاولة لهدم الكعبة\n الأولى كانت على يد تُبّع إللي اتكلمنا عنه في الجزء الأول \nوكان من ضِمن الجيش بتاعه فيل ضخم اسمه محمود،\nوبدأ يتحرك من اليمن باتجاه الكعبة، وسمعت العرب بأن أبرهة عايز يهدم الكعبة،\nوكان في رجل من أشراف العرب اسمه ذو نَفَر جمع بعض المقاتلين وجهّزوا نفسهم عشان يحاولوا يوقفوا جيش أبرهة من إنه يهدم الكعبة،\nوحاولوا يوقفوا جيش أبرهة لكنهم انهزموا وتم أسر ذو نفر،\nوأخذه أبرهة معاه في الجيش أسير،\nخرجت لجيش أبرهة قبيلة تانية تقاتله عشان ميهدمش الكعبة بقيادة واحد اسمه نُفيل بن حبيب،\nواتهزمت القبيلة وأُسر نُفيل، وصل جيش أبرهة للطائف فخاف أهل الطائف من جيش أبرهة وإنه يهدم عليهم الطائف،\nفقالوا له ملناش دعوة مش هنعترض طريقك ولا هنعمل حاجة وعشان نثبت إننا مسالمين ممكن نبعث معاك واحد يدلك على مكان الكعبة،\nفتطوع واحد اسمه أبو رُغَال وقال له أنا هدلّك على مكان الكعبة،\nوطبعا دي خيانة \nوراح مع أبرهة عشان يَدُله على طريق الكعبة ،وهو في الطريق بين مكة والطائف مات واندفن فكانت العرب بترجم قبره بالحجارة بسبب خيانته \nالمهم وصل أبرهة وجيشه لأطراف مكة وفي الطريق كان في إبل ..جِمال يعني في الطريق فأخذها جيش أبرهة،\n وكانت الجمال دي حوالي مئتين جمل يملكها سيد مكة في الوقت ده أو خلونا نقول رئيس مكة،\nوكان اسمه عبد المطلب، وكان رجل كبير في السن فجاء له الخدم بتوعه وقالوا له جيش أبرهة جاء وأخذ البعير بتاعتك،\nفخرج له عبد المطلب وطلب إنه يقابله، \nلكن أبرهة رفض فتوسط عبد المطلب عند الأسير ذو نفر إنه يكلم أبرهة فقال له:\nأنا أسير مقدرش أعمل لك حاجة\nلكن أنا اتصاحبت على سائس الفيل، يعني الرجل المسؤول عن قيادة الفيل،\nوسائس الفيل ده كان له مكانة عند أبرهة،\nفكلم ذو نفر سائس الفيل عشان يتوسط لعبد المطلب عند أبرهة عشان يرضى يقابله،\nفوافق أبرهة إنه يقابله وكان عبد المطلب عليه هيبة ووقار وكان جميلا جدا فلما شافه أبرهة قام له توقيرا له،\nوكان ابرهة قاعد على حاجة زي العرش كده فنزل من على العرش ده وجلس جنب عبد المطلب على بساط في الأرض من كتر ما أبرهة حس بهيبة من عبد المطلب، وبعدين قال للترجمان اسأل عبد المطلب عايز إيه؟\nفعبد المطلب قال له:\nجيشك أخذ مئتين بعير بتوعي فأنا عايزك ترجعهم لي\nفأبرهة قال له:\nأنت عجبتني لما شفتك وتوقعت إنك هتطلب مني إني أسيب البيت إللي هو دينك ودين آباءك،\nلكن لما تكلمت أنا زهدت فيك\n...يعني استقليتك أوي\nبتكلمني وتطلب مني أسيب البعير وحتى متطلبش مني أسيب البيت المعظم عندكم\nفقال له عبد المطلب :\nأنا رب الإبل ..والبيت له رب سيمنعه ويحميه\nخرج عبد المطلب من عند أبرهة وأمر أهل مكة إنهم يخرجوا برة مكة ويطلعوا على الجبال عشان جيش أبرهة ميؤذيش أهل مكة ويسيبوا البيت الحرام لأبرهة عشان يهدمه.\n☆طبعا ناس كتير أوي معجبة بكلمة عبد المطلب: للبيت رب يحميه، ومفكرين إنها بتدل على اليقين والثقة في الله وساعات بيقولوها على الإسلام كمان،\nيعني بيقولوا للدين رب يحميه ومفكرين إن دي حاجة جميلة ومش واخدين بالهم إن دي قمة السلبية \nيعني الإنسان يعيش كده يدوّر على لقمة عيشه ويعيش حياته لنفسه وأولاده وملذّاته ويسيب الدين لربنا هو يحميه؟!!\nوامشي جنب الحيط وكُل عيش وعادي يعني سلم دينك للأعداء ومتدافعش عنه واقعد اتفرج عليهم،\nزي ما أهل مكة عملوا...سابوا الكعبة لأبرهة وقعدوا يتفرجوا عليه، طيب فين دفاعك عن دينك...مفيش\nزي إللي بيقول اللهم أهلك الظالمين بالظالمين وأخرجنا من بينهم سالمين،\nطيب يابني دورك فين؟\nإنت عايز عِزّة وتمكين في الأرض وإنت قاعد تتفرج\nده حتى بيقولوا في المثل: الحاجة إللي بتيجي بالساهل بتروح بالساهل\nطبعا احنا بنفرح لما الظالمين يضربوا في بعض، لكن ميبقاش اعتمادنا على كده في النصر عليهم، لازم يكون لنا دور في نُصرة الدين\nالمهم، الجنود جابوا الفيل عشان يهدم الكعبة في اللحظة دي الأسير نُفيل بن حبيب إللي كان معاهم عرف يفك نفسه من الأسر،\nوجري ناحية الفيل واتعلق في أذنه وقعد يقول له:\nابْرُك محمود ..ابْرُك محمود فإنه بيت الله العظيم\nيعني اقعد يا محمود ومتسمعش كلامهم...إللي عايزينك تهدمه ده بيت الله الحرام،\nراح الفيل قاعد في الأرض ومرضاش يقوم\nقعدوا يضربوا فيه عشان يقوم مش راضي،\nوجّهوه نحو اليمن قام يجري وجهوه ناحية الشام اتحرك وجّهوه ناحية الكعبة قعد ومتحركش\nهرب حبيب بن نُفيل وطلع على رؤوس الجبال مع أهل مكة،\nجنود أبرهة وهمّ عمالين يحاولوا يحركوا الفيل لقوا سواد جاي من بعيد بيقرب عليهم\nالسواد بيقرب وبدأ يظهر إيه هو السواد ده ..لقوها طيور جاية عليهم ورا بعض من كل مكان،\nبيوصفها العلماء إنها طيور عاملة زي العصافير،\n\"أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ ۩أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ ۩ وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ\"\nكل طير معاه ثلاث حجارات، واحدة في منقاره وحجارة واحدة في كل قدم،\nحجم الحجرة الواحدة في حجم حبة العدس أو الحمص،\nويُقال إن الحجارة دي كانت من نار ويُقال إنها كانت من طين يابس متحجر شديد القوة من جهنم،\n\"تَرْمِيهِمْ بِحِجَارَةٍ مِنْ سِجِّيلٍ\"\nبدأت الطيور ترمي الحجارة دي على جنود جيش أبرهة وأي حد يتصاب بالحجارة دي كأن مرض بينتشر في جسمه ويبدأ لحم جسمه يسقط\nبدأ جيش أبرهة يهرب، حتى أبرهة نفسه هرب بس هيهرب من مين \nالحجارة أصابته وقُتل أبرهة وكل من كان في جيش أبرهة\n\"فَجَعَلَهُمْ كَعَصْفٍ مَأْكُولٍ\"\nوالعصف المأكول يعني الزرع إللي الحيوانات أكلته وداسته،\nيُقال إن في بعض الجنود هربوا وهم جرحى ووصلوا لليمن وحكوا إللي حصل للناس إللي في أرض اليمن، فالله أعلم هل الكلام ده صحيح ولا لأ\n《هتلاقوا الكلام ده في كتاب البداية والنهاية وتفسير القرآن لابن كثير》\n☆في ناس ممكن تسأل طيب ماهو ربنا أنقذ قريش أهه وأهلك جيش أبرهة..ليه ربنا لا يرسل الطير الأبابيل على الكفار إللي بيعذبوا المسلمين وبيقتلوهم زي بورما مثلا\nبكل بساطة لأننا لسنا في زمان أبرهة\n◇أولا:\nربنا لم يهلك جيش أبرهة عشان خاطر أهل قريش،\nربنا أهلك جيش أبرهة لأنه كان عايز يهدم الكعبة،\nوإلا فأبرهة وجيشه نصارى..أهل كتاب.. يعني أقرب إلى الله من المشركين إللي بيعبدوا الأصنام\nده غير كده الكعبة دي لها دور في حياة المسلمين لحد آخر الزمان، ومكة هي المكان إللي هيتولد فيه رسول الله ﷺ،\nفلازم الكعبة تكون موجودة عشان كده ربنا حفظ الكعبة من جيش أبرهة\n◇ثانيا:\nسنة إهلاك الظالمين أو الكافرين بخارقة.. بمعجزة يعني بدون تدخل من المؤمنين، زي الطوفان أو زي إللي حصل مع أبرهة انتهت خلاص،\nآخر معجزة لنصر الدين بدون تدخل من المؤمنين كانت حادثة الطير الأبابيل،\nبعد ما الإسلام جاء الوضع تغير...ممكن تحصل المعجزة لكن بعد ما المسلمين أو المؤمنين يعملوا إللي عليهم،\nزي ما حصل في غزوة بدر، حصلت معجزة نزول الملائكة وقاتلوا مع المؤمنين بعد ما المؤمنين أخذوا بالأسباب وعملوا كووول إللي يقدروا عليه زي ماهنشوف في وقتها بالتفصيل إن شاء الله\nفربنا ساعدهم بمعجزة نزول الملائكة،\nلكن لو المسلمين مقصّرين في الأخذ بالأسباب ومش عاملين إللي عليهم مش هتنزل أي معجزة\nيعني القاعدة في الإسلام دلوقتي :\n\"يَا أَيُّهَا الَّذِينَ آمَنُوا إِن تَنصُرُوا اللَّهَ يَنصُرْكُمْ\"\nالمسلمين يُقتلوا في بورما مثلا لمجرد إنهم مسلمين وهم مستسلمين حتى مش بيدافعوا عن نفسهم وجهاد الدفع فرض عليهم، يعني يجب عليهم إنهم يدافعوا عن نفسهم بأي شيء ولو قتلوا فهم شهداء، لكن لو مستسلمين كده فربنا لن يدافع عنهم\nلكن لو دافعوا عن نفسهم ودافعوا عن دينهم وعملوا إللي يقدروا عليه ربنا هيؤيدهم بمعجزات زي معجزة الطير الأبابيل\nعندنا سنن كونية مش هتتغير مهما استنينا\n\" إِن تَنصُرُوا اللَّهَ يَنصُرْكُمْ\"\nناخد القاعدة دي وننزلها على حياتنا احنا بقى..هل احنا في حياتنا بنطبق القاعدة دي؟\nهل أنا بنصر دين ربنا في حياتي؟\nهل أنا ببعد عن كل المحرمات سواء الكبائر أو الصغائر إللي ربنا نهى عنها وبعمل إللي أمرني به؟\nولا بدوّر على أي مخرج من هنا ولّا من هنا عشان أعمل إللي أنا عايزه وبعدين أقول يارب انصرني على إللي ظلمني؟\nأنا شخصيا على مدى سنين طويلة كنت بستغرب جدا من الناس إللي بيحصل لها ابتلاءات شديدة جدا أو الناس إللي بتتعرض للقتل والتعذيب و...و...\nهو ربنا ليه فعلا لا ينصرهم..ليه ربنا لا يستجيب دعاؤهم وأسئلة كثيرة،\nلحد ما فهمت إن إللي بيحصل للناس دي مش بيخرج برة معنيين اتنين:\n◇المعنى الأول:\nإن الناس دي لها رسالة زي غلام أصحاب الأخدود إللي اتكلمنا عنه المرة إللي فاتت،\nوزي الأنبياء والأولياء المعروف عنهم بإنهم مش بيعملوا معاصي أو ذنوب،\nفالقسم ده بيكون قتله أو تعذيبه مثلا لرسالة معينة\n◇المعنى الثاني هو: \nإن تنصروا الله ينصركم، لما بنظر لحياة الناس المعذبة أو المبتلاة دي《 نظرة تدبر》\nلا نظرة شفقة ولا شماتة ولا أي حاجة تانية،\nنظرة تدبر وتفكّر فقط\n \nيعني أقعد أفكر وأركز في الأحداث وإيه إللي ممكن يكون وصلهم للوضع بتاعهم ده،\nألاقيهم بيعملوا كوارث في حياتهم وهم مش واخدين بالهم منها نهائي وممكن تكون كبائر كمان ومجاهرين بها \nوبيدعوا ربنا ومفيش استجابة والبلاء يزيد عليهم،\nوهم مستمرين برده على عدم إقامة شرع ربنا في نفسهم\nطيب يا جماعة ماهو إن تنصروا الله بتطبيق شرعه في حياتكم هينصركم...وفي نفس الوقت لو منصرتهوش هتنزل عليكم المصائب ورا بعض،\n\"وَمَا أَصَابَكُم مِّن مُّصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ\"\nوللأسف المعنى الثاني ده هو الحال الغالب على الناس\nخدوا بالكم من القاعدة دي كويس لأنها هتكون معانا طووول السيرة النبوية \n《إن تنصروا الله ينصركم》\nبعد هزيمة جيش أبرهة بالمعجزة إللي حصلت وإللي شافها أهل مكة كلهم،\nفي نفس عام الفيل ده يُقال بعد خمسين يوم وُلد لعبد المطلب حفيد..الحفيد ده هيكون سبب في تغيّر الأرض في المستقبل،\nمين هو الحفيد واسمه إيه ومين أبوه ومين أمه؟\nده إللي هنعرفه الجزء الجاي إن شاء الله\n☆\n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الرابعة\n#إعادة_حفر_زمزم\n#ولادة_محمد_ﷺ \nوقفنا المرة إللي فاتت عند عبد المطلب لما اتولد له حفيد بعد حادثة الفيل بحوالي خمسين يوم،\nقبل ما نتكلم عن تفاصيل ولادة حفيد عبد المطلب،\nخلونا نشوف مين هو عبد المطلب ده\nقلنا إن عبد المطلب ده كان سيد مكة يعني رئيس مكة بلا مُنازع،\nوالرئيس معروف إنه بيستقبل رؤساء زيه وبيقعد معاه كُبراء الناس وبيستقبل وُفود من هنا وهناك،\nلكن إزاي أصلا عبد المطلب إللي هو من قريش كان رئيس مكة وقبيلة خزاعة هي إللي كانت بتحكم\nإحنا عارفين إن إللي كان بيحكم مكة من زمن إسماعيل هو إسماعيل وأبناؤه إللي هم من قبيلة جُرهم،\nوخزاعة اغتصبوا منهم الحكم،\nفكان في واحد اسمه فِهر وبيلقبّوه باسم قريش من ذرية إسماعيل عليه السلام كان موجود في مكة وعايش فيها بعد ما خُزاعة سيطرت على مكة،\nفكان في واحد من ذرية فِهر ده أو خلينا نقول عليه قريش: اسمه قُصَي بن كِلاب وكان عايز يرجّع حكم مكة لسلالة إسماعيل عليه السلام،\nوكان قصي بن كلاب كريم وغني وكان معروف بنسبه بين أهل مكة،\nفخطب بنت رئيس خزاعة فوافق أبوها وتزوجها قصي بن كلاب، فشرفه ومكانته زادت بين الناس،\nلما مات رئيس مكة من خزاعة أعلن قصي بن كلاب إن هو رئيس مكة،\n وطلب من الناس أنصاره وأقاربه إنهم يقفوا معاه،فبقى في فريقين، فريق قصي بن كلاب وفريق خزاعة ،\nحصل بينهم حرب ولما كانوا خلاص هيفنوا بعض، تدخل الحكماء وقالوا خلّونا نحتكم لرجل من المُعمّرِين،\nيعني عمره طويل وعايش في الدنيا سنين طويلة ،\nوقعدوا يحلفوا وياخدوا العهود من بعض إن إللي هيحكم به الرجل المُعَمّر ده هو إللي هيمشي على الكل ومحدش يعترض\nراح قصي بن كلاب وقادة خزاعة للمُعمّر، وقصي بن كلاب قعد يقول له ده ملك آبائي ،\nإسماعيل جدي وهو أول من سكن مكة وزمزم اتحفرت له وخزاعة دول مغتصبين،\nومحدش من خزاعة قادر يفتح بؤه ..هيقولوا إيه\nفالرجل المُعَمّر ده حكم بكل شيء لقصي بن كلاب\nوبقى هو حاكم مكة وكان كريم جدا مع الناس،\n وبنى لهم حاجة زي قاعة اجتماعات كده وسماها:\n《دار النّدوة》\nأي قرار مهم بيجتمعوا وبيقرروا في الدار دي سواء قرار حرب أو مشاورة أو حتى زواج ، زي ما هنشوف بعدين إيه القرار إللي قريش أخذته بعدين في الدار دي\nبعد ما كِبر قصي بن كلاب في السن شاف إن أبناؤه كلهم عندهم شرف ومكانة بين الناس إلا ابن واحد بس اسمه عبد الدار،\nفكتب له قصي بن كلاب كل حاجة لها علاقة بالشرف،\nيعني هو إللي هيكون مسؤول عن سقاية الحجيج، ومسؤول عن دار الندوة وكل حاجة خاصة بالشرف،\nفلما مات قصي بن كلاب أبناؤه اتخانقوا ،عايزين يأخذوا إللي عند عبد الدار وكان هيحصل بينهم قتال،\nهو خلاص اتحقق له المطلوب وبقى له شرف ومكانة بين الناس\n☆سبحان الله ...الناس تتخانق على الأموال وهم بيتخانقوا على الشرف ،\nبيتخانقوا على مين يخدم الكعبة ومعاهم حق بصراحة حد يطول يخدم الكعبة بيت الله ويخدم الحجاج\nبس طبعا مش هينفعهم يوم القيامة خدمة بيت الله وهم على الكفر\nالمهم، \nاتفقوا إنهم يوزّعوا الحاجات دي بينهم،\nيعني عبد الدار وأبناؤه يكونوا مسؤولين عن سِدانة الكعبة، يعني يكونوا مسؤولين عن الكعبة يقفلوها ويفتحوها ويغسلوها ويغيّروا كسوتها ويستقبلوا زوراها وهكذا.\nوعبد مناف وأبناؤه مسؤولين عن سِقاية الحجاج،\nوكانوا بيسقوا الحجاج من خارج مكة لأن زمزم كانت اندفنت خلاص زي ما قلنا قبل كده\nعبد مناف ده كان من أبناؤه واحد اسمه هاشم وواحد اسمه المُطّلب،\nهاشم تزوج من واحدة من خارج مكة وكان له ولد اسمه شَيْبة وكان عايش مع أمه خارج مكة،\nفلما مات أبوه هاشم جاء عمه المُطلب وطلب إنه يأخذه عشان يعيش مع أعمامه في مكة،\nفلما وصلوا مكة الناس ظنت إن المُطّلب اشترى عَبد فقالوا 《عبد المطلب》\nفقال لهم لأ ..ده ابن أخويا ..فاشتهر شَيبة بين الناس بعبد المطلب إللي بنتكلم عنه دلوقتي وإللي هو مسؤول عن سقاية الحجاج\nفهو اسمه عبد المطلب بن هاشم بن عبد مناف بن قُصي بن كلاب بن فِهر إللي هو قريش وبينتهي نسبه إلى إسماعيل عليه السلام \nفي يوم من الأيام كان عبد المطلب نائم فسمع حد بيقول له في الحلم احفر طيبة،\nفعبد المطلب قال : وما طيبة\n ..محدش رد\nثاني يوم وهو نايم سمع حد بينادي عليه وبيقول له : احفر برّة ، فقال عبد المطلب : وإيه برّة دي \nفراح الصوت \nثالث يوم جاله نفس المنادي وقال له : احفر المَضْنونة فقال : وهي إيه المضنونة \n...فراح الصوت برده\nاليوم الرابع وهو نايم سمع برده حد بينادي عليه وبيقول :\nاحفر زمزم\nفقال وما زمزم \nفالمنادي رد عليه المرة دي وقال:\n\"لا تنزِف أبدا ولاتَزم ..تسقي الحجيج الأعظم وهي بين الفَرثِ والدم عند نقرةِ الغراب الأَعْصم عند قرية النمل\"\nلا تنزف يعني مش بتخلص أبدا مهما الناس شربوا منها،\nولا تَزم يعني مفيهاش عيب \nفلما صِحي عبد المطلب من النوم أخذ ابنه الوحيد وكان اسمه الحارث وراحوا عند الكعبة يدوّروا على المكان إللي بين الفَرْث والدم،\nوصل عبد المطلب عند الكعبة ومعاه الفأس والناس من قريش بيبصوا عليه مستغربين بيعمل إيه ده بالفأس\nوبدأ عبد المطلب يدوّر على العلامات إللي سمعها في الرؤيا،\nفشاف ناس بيذبحوا بقرة عند حجر اسمه إِِسَاف كان كفار قريش بيعبدوه وبيذبحوا عنده الذبائح للآلهة بتاعتهم،\nفنزل الدم من البقرة فقامت تجري لحد ما وقعت عند الجر الثاني وهو صنم اسمه نَائِلة،\nفالناس كملوا ذبح البقرة وشقوا بطنها وطلعوا الفَرث إللي هو الأمعاء والحاجات إللي بتكون في البطن،\n☆بالمناسبة إساف ونائلة دول كانوا أصلا بشر وكانوا من أهل اليمن وكانوا بيحبوا بعض،\nفتقدم إساف لخطبة نائلة فأبوها رفض، فاتفقوا هم الإثنين إنهم يتقابلوا في موسم الحج،\nفلما اتقابلوا وفي غفلة من الناس زنى إساف بنائلة عند الكعبة فمسخهم الله حجرين، فالناس أخذت الحجر ووضعوا واحد على الصفا والثاني على المروة عشان الناس تَعتَبر،\nفلما جاء عمرو بن لُحي نزل الحجرين وأمر الناس يعبدوهم \nومع الوقت الناس نسيت قصتهم وبقوا آلهة تُعبد ومبقاش حد عارف قصتهم إلا القليل\nالمهم عبد المطلب شاف الفرث والدم.. بس واقف محتار ..صعب يحفر المكان ده كله\nفوهو واقف لقى غراب أعصم جاء ونقر بمنقاره في مكان معين بين الفرث والدم، وكان موجود في المكان ده قرية النمل،\nوالغراب الأعصم هو الغراب إللي رجله ومنقاره لونهم أحمر وفي ريشة واحدة بيضاء على ريش جناحه الأسود،\nفعرف عبد المطلب إن هو ده المكان المقصود فمسك الفأس وبدأ يحفر زمزم،\nفأهل مكة قاموا عليه...إنت بتحفر عند المكان إللي بنذبح عنده الذبائح للآلهة\nفقال لابنه الحارث ابعدهم عني لحد ما أخلص،\nفقعد يحفر والناس بتحاول توقفه لحد ما لقى بداية المية بتطلع فقال: الله أكبر ، فالناس قالوا أكيد لقى إللي بيدور عليه،\nفلما شافوا المية عرفوا إنها زمزم وقالوا إحنا هنشاركك فيها دي مية جدنا إسماعيل،\nفقال لهم: تشاركوني إزاي وأنا إللي مكتشفها أصلا\nفقالوا خلاص نحتكم للكاهنة ،\nفخرجوا للكاهنة وكانت في بلد تانية وهم ماشيين في الصحراء المية خلصت منهم وكانوا خلاص هيموتوا،\nفناقة عبد المطلب ضربت برجلها الأرض فخرج زي نبع ماء كده،\nفنادى على أصحابه عشان يشربوا معاه فقالوا:\nوالله إللي سقاك المية دي في الصحراء هو إللي أعطاك زمزم ،\nخلاص زمزم لك ، ورجعوا تاني لمكة وبقى عبد المطلب هو إللي بيسقي الحجيج من زمزم\nبعد حادثة زمزم عبد المطلب مكنش عنده أبناء غير الحارث ولما كان بيحفر زمزم مكنش في حد بيدافع عنه غير الحارث،\nفنذر عبد المطلب نَذْر ..قال:\nلو ربنا رزقني عشرة من الولد هذبح واحد فيهم قربة لله،\nففعلا ربنا رزقه بعشرة من الولد منهم:\nالعباس، حمزة، عبد مناف وكان يلقب بأبو طالب، وعبد العُزى  وكان لقبه أبو لهب، وأخيرا عبد الله وكان أصغرهم.\nلما اكتمل العشرة أبناء راح عند الكعبة وكتب اسماؤهم على عِصيان كده عشان يختار واحد منهم، وكان بيقول لو طلع سهم أي حد غير عبد الله فأنا معنديش مشكلة، لأنه كان أحب أبناؤه له،\nفلما اختاروا من العصيان طلع اسم عبد الله\nفعبد المطلب معندوش حل تاني لازم يوفي بنذره، فأخذ عبد الله ولسه هيذبحه الناس وقفته ،\nويقال إن العباس شَد عبد الله من إيد عبد المطلب وهو لسه هيذبحه فالسكين عوّرت وجه عبد الله وبقى في وجهه علامة لحد ما مات،\nالمهم مكنش حد راضي إن عبد المطلب يذبح ابنه عبد الله،\nفقال لهم لازم أوفي بنذري\nفقالوا له: خلينا نسأل الكهنة فراحوا للكَهنة وسألوهم نعمل إيه؟\nفالكهنة قالوا:\nاكتبوا اسم عبد الله على عصا وده يكون سهم عبد الله وخلوا قصاده سهم عشرة من الإبل،\nوكل ما يطلع سهم عبد الله زيدوا في الإبل لحد ما يطلع سهم الإبل،\nفبقوا كل ما يطلع سهم عبد الله يزيدوا الإبل لحد ما وصل عدد الإبل لمائة ناقة وذبحوها فداء لعبد الله بن عبد المطلب،\nتزوج عبد الله من امرأة اسمها آمنة بنت وَهب وكان وهب من بني عبد مناف من ذرية إسماعيل عليه السلام،\nوأم آمنة كانت من يثرب فكانت آمنة بتعيش عند إخواتها في يثرب،\nفعبد الله تزوج آمنة في يثرب وبعدين رجعوا كلهم لمكة،  وحملت آمنة بطفل وبعد كم شهر من الحمل...مات زوجها عبد الله\nيعني الطفل حفيد عبد المطلب إللي هيتولد ..هيتولد يتيم \nكانت آمنة بنت وهب بتقول: إنها محستش بحمل خالص، حملها كان خفيف ومكنش فيه أي تعب،\nوشافت آمنة رؤيا قبل ما تولد ، شافت إنها هتولد ولد وهيخرج معاه نور يملأ الارض لحد ما يُضيء قصور الشام\n《الكلام ده في حديث صحيح》\nوجاء وقت الولادة... في يوم الإثنين اثنا عشر من ربيع الأول على أرجح الأقوال من عام الفيل ولدت آمنة ولد،\nومع خروجه.. الأوضة إللي كانت فيها اتملت نور وإللي حضروا الولادة كلهم شافوا النور ده وبقوا يحكوا للناس عن النور إللي شافوه،\n☆ملحوظة،\nيوم الولادة مش معروف بالضبط هو كان يوم إيه، هل هو اليوم الثامن من ربيع الأول ولّا الاثنا عشر ولّا غيره،\nلكن أرجح أقوال العلماء فيه، إنه كان الثاني عشر من ربيع الأول في عام الفيل\nالمهم،\nعبد المطلب سمّى الطفل 《محمد》والإسم ده مكنش حد بيسميه قبل كده أبدا لحد وقت قريب جدا قبل ولادة محمد حفيد عبد المطلب ،\nكان أهل الكتاب بيقولوا إن في نبي هيخرج قريب والزمن ده زمان نبي وهو اسمه محمد ،\n فسمع الكلام ده كذا واحد فكل واحد منهم سمى أول مولود له محمد لعله يكون هو المقصود،\nوكان من إللي سمعوا الكلام ده عبد المطلب،\nفلما اتولد له حفيده سماه محمد على أمل إنه يكون هو النبي المذكور،\n وكمان عبد المطلب لما أهل قريش سألوه إنت سميته إيه قال لهم محمد فاستغربوا الإسم وقالوا له:\nليه سميته اسم مختلف مكنش موجود في أسماء أحد من أبائك أو أجدادك\nفقال لهم:\nأنا أرجو إن أهل الأرض كلهم يحمدوه\nففي اليوم السابع من ولادة 《محمد》 ذبح عبد المطلب الذبائح له،\nوختنه على عادة العرب في ختان أبنائهم، فهم لم يُولد مختون على أرجح الأقوال.\nومن الأحداث إللي حصلت يوم مولده إن حسّان بن ثابت الشاعر المعروف كان في يثرب في الوقت ده وكان عمره سبع سنين فسمع واحد من أحبار اليهود بينادي:\nياااا معشر يهووود ...فاليهود إللي كانوا في المدينة قالوا في إيه مالك\nفقال لهم: ظهر نجم أحمد إللي مش بيظهر إلا لو خرج\nونجم أحمد ده نجم مختلف عن باقي النجوم له صفات معينة كان اليهود والنصارى يعرفوها مش بيخرج إلا لما يتولد آخر نبي إللي اسمه أحمد\n◇أما موضوع انطفاء نار المجوس يوم مولده وسقوط أربعة عشرة شُرفة من قصر كسرى وسقوط الكنائس حول بُحيْرة ساوة بعد ما غارت جوة الأرض ومبقاش لها أثر ..فكل ده من الأحاديث الضعيفة أو الموضوعة \nوكانت حادثة الفيل من المعجزات إللي كانت بتمهد لولادة محمد ﷺ،\nفربنا حفظ مكة لأن فيها الكعبة وكمان عشان هيخرج منها آخر الأنبياء\nفاكرين لما قلنا في قصة تُبّع لما كان عايز يهدم الكعبة د،\nأحبار اليهود إللي معاه قالوا له ربنا هيهلكك لأن ده بيت الله الوحيد على الأرض والبلد دي هيخرج منها نبي\nأهه لما واحد حاول يهدم البيت ويخرّب مكة ربنا أهلكه\nوزي ما قلنا المرة إللي فاتت ربنا لمّا أهلك جيش أبرهة مكنش عشان قريش، \nولكن عشان يحفظ الكعبة ويحفظ البلد إللي هيخرج منها النبي\nوخصوصا إن أهل مكة سابوا أبرهة يهدم البيت وخرجوا من مكة وهم أصلا المسؤولين عن الكعبة وحمايتها\nزي ما شرحنا النهاردة،\n ومأخذوش بالأسباب المطلوبة عشان يحموها، بعكس القبائل العربية الثانية، إللي حاولوا محاولة ولو بسيطة إنهم يدافعوا عن الكعبة\nزي بالضبط لما تحصل مشكلة في أي بلد إسلامي،\nتلاقي الناس إللي في البلد مش في دماغهم ومش فارق معاهم، وناس تانية عندها حَميّة ويحاولوا يعملوا أي حاجة يساعدوا بيها،\nفطبعا النتيجة مش هتكون النتيجة المطلوبة، لأن مفيش الأخذ الحقيقي بالأسباب \nمجرد مجهودات متفرقة من هنا وهنا\nإزاي نشأ الطفل محمد وهل حصل معاه معجزات خلال نشأته ولّا كانت حياته عادية؟\nده إللي هنعرفه الجزء الجاي إن شاء الله "}, {"n": 43, "l": "الجزء الخامس | نشأة رسول الله | حادثة شق صدره | ...... | والجزء السادس | مصير ام واب وجد النبي | حلف الفضول", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الخامسة\n#نشأة_رسول_الله_ﷺ \n#حادثة_شق_صدر_رسول_الله\nوقفنا المرة إللي فاتت عند ولادة محمد بن عبد الله حفيد عبد المطلب وشفنا الأحداث إللي حصلت يوم ما اتولد وعرفنا ليه اتسمى باسم محمد،\nكان من عادة قريش إنهم لما يتولد لهم مولود مكنوش بيربّوه في مكة وكانوا بيرسلوه خارج مكة يرضع ويتربى هناك أول سنتين أساسي لأسباب كثيرة منها:\n◇إن الحُجاج لما كانوا بيأتوا لمكة كانوا بيقعدوا فيها فترة طويلة،\nفالأطفال لما بيختلطوا بالناس لغتهم العربية مش بتكون فصيحة ومضبوطة مائة بالمائة \nوقريش عايزين عيالهم يكونوا متمكنين من اللغة، فكانوا بيرسلوا أبناؤهم للبدو يتربوا هناك لحد ما لسانهم يتعود على اللغة العربية الصحيحة وبعدين يرجعوا لمكة،\nزي مثلا في عصرنا لما الطلبة بتسافر للبلاد الأوروبية وتعيش مع أسر أجنبية عشان يتعلموا منهم اللغة الأجنبية مضبوطة \nواللغة العربية مهمة جدا عند العرب، تقدروا تقولوا إنها حياتهم، كان الواحد منهم لما يكون فرحان يقول شعر، \nولما يكون زعلان يقول شعر وفي الحرب شِعر وهو بيموت بيقول شعر\nفإزاي هيبهروا الناس بكلامهم ويشتهروا بين العرب وهم مش متعلمين لغة عربية صحيحة\n◇من الأسباب كمان إنهم كانوا عايزين عيالهم يتربوا على حياة الخشونة، ميكنوش مدلعين يعني\nلأن إللي بيتربى في المدينة بيكون متعود على حياة الترف،\nلكن إللي بيتربى في البدو مثلا بيكون متعود على صعوبات الحياة فبيكون شخصيته أقوى ومُتحمّل للمسؤولية\n◇السبب الثالث:\nإن مكة بيأتي لها الناس من كل مكان فكان فيها أمراض،\nبعكس الصحراء إللي هواءها نظيف فبيكون نادر فيهم المرض وعندهم صحة\nفكانت قريش بترسل أبنائها للأعراب من صغرهم عشان يتربوا عندهم.\n☆طبعا احنا ممكن نستغرب ونقول إزاي واحدة ترضى إن ابنها يبقى بعيد عنها ومتشفوش إلا بعد سنتين وواحدة تانية هي إللي ترضعه\nتقدروا تقولوا إن الموضوع ده عادة عندهم والناس كلها بتعمل كده فمحدش بيفكر في الموضوع أصلا وشايفينه عادي\nوالأعراب نفسهم كانوا بيوافقوا إنهم يأخذوا الأطفال من باب المنفعة، \nيعني هياخدوا أموال مقابل رعايتهم للأطفال،\nلكن هم مكنوش بيطلبوا مبلغ معين عشان كانوا شايفين إن عيب المرأة تأخذ أُجرة على لبنها،\nفكان أبو الطفل بيعطوا للأم إللي بترضع مكافأة أو بلغتنا احنا إكرامية\nالمهم في الوقت إللي اتولد فيه محمد بن عبد الله حفيد عبد المطلب جاءت لقريش مرضعات من بني سعد عشان يأخذوا الأطفال من مكة،\nفكانت النساء في مكة بيعرضوا أبائهم على المرضعات،\nوكانت آمنة بنت وهب بتعرض ابنها محمد على المرضعات زي باقي النساء،\nفأول ما يعرفوا إن محمد يتيم يرفضوا يأخذوه\nلأن مين إللي هيعطيهم إكرامية\nأبوه ميت وحتى جده من وجهة نظرهم مش هيكون حريص عليه زي أبوه.\nوكان من ضِمن المرضعات دول واحدة اسمها حليمة بنت أبي ذُؤَيب إللي هي حليمة السعدية،\nوكانت فقيرة جدا وكانت حتى معندهاش لبن يكفي ابنها،\nوحتى الأتان إللي كانت راكبة عليها كانت ضعيفة وهذيلة وكانت بتأخر الناس وهم ماشيين عشان مش قادرة تمشي،\nالأتان أنثى الحمار\nفبعد ما كل واحدة من المرضعات أخذت رضيع من مكة وخلاص راجعين، حليمة ملقتش رضيع تأخذه،\nفقالت لزوجها الحارث: أنا مش عايزة أرجع من غير رضيع وأصحابي كلهم معاهم رضيع، أنا هروح آخذ اليتيم ده\nفزوجها الحارث قال لها:  خلينا نأخذه يمكن يكون بركة علينا.\nفرجعوا وأخذوا محمد اليتيم،\nوكانت بترضعه مولاة عمه عبد العزى إللي كنيته أبو لهب\nوالمولاة معناها امرأة كانت أَمَة ..عبدة يعني إذا صحت الكلمة \nوسيدها حررها،\nوالمرضعة دي أرضعت كانت أرضعت قبل كده حمزة بن عبد المطلب أخو عبد العزى،\nفبقى محمد بن عبد الله بن عبد المطلب وعمه حمزة بن عبد المطلب إخوة من الرضاعة\n \nحليمة السعدية بتقول:\n أول ما أخذت اليتيم ورجعت لمكان رَحْلي يعني المكان إللي الناس متجمعين فيه وبايتين فيه زي نقطة تجمع كده عشان الصبح ينطلقوا منه لبلدهم؛\nلقت صدرها اتملى لبن فرضعته وشبع ورضعت ابنها وشبع والطفلين ناموا\nوابنها مكنش بينام أصلا من الجوع وكل ليلة بيبقى بيعيط،\nوبعدين زوجها كان بيشوف الناقة بتاعتهم لقى ضرعها مليان لبن مع إنها عجوز\nفحَلب الناقة وشرب هو وزوجته وشبعوا وناموا وكانت بالنسبة لهم أحسن ليلة يناموها،\nفلما صحيوا تاني يوم زوجها بيقول لها:\nيا حليمة إنتي شكلك أخذتي نَسَمة مُباركة \nقالت له: فعلا والله\nوهم راجعين الأتان إللي حليمة راكبة عليها بتسبق القافلة كلها، وحليمة عمالة تهدّي فيها ودي منطلقة، لدرجة إن النساء إللي كانوا معاها قالوا لها:\nهو إيه إللي جرى للأتان بتاعتك\nهو إنتِ غيرتيها ولا هي نفسها \nفقالت لهم :مغيرتهاش ولا حاجة ..هي نفس الأتان إللي أنا جيت عليها \nولما وصلوا أرض بني سعد ..حليمة بتقول إن مفيش أرض جدباء مفيهاش زرع زي أرض بني سعد\nلكن فجأة لقت الغنم بتاعها راجع من المرعى شبعان والضرع بتاعهم مليان لبن، \nفالناس مستغربين اشمعنى حليمة \nفكانوا بيقولوا للغلمان بتوعهم روحوا ارعوا مع غنم حليمة \nوعاش محمد بن عبد الله مع حليمة في بني سعد، قالت عنه حليمة كان بيكبر بسرعة،\nيعني لما كان وصل عمره سنتين كأن عمره ست سنين، وكان بيتكلم كلام واضح جدا وهو عمره سنتين \nبعد ما بتخلص السنتين بتوع الرضاع الناس بترجع الأطفال لأهلها بعد ما يكونوا فطموهم ويشوفوا إللي عايز يسترجع أبناؤه أو يخليهم مع البدو مدة أطول،\n حليمة فطمت محمد وأخذته هي وزوجها الحارث ورجعوا لأمه آمنة زي باقي الناس،\nفلما وصلوا عندها قعدوا يقنعوها إنهم يرجعوا بمحمد مرة تانية ويخلوه عندهم عشان خايفين عليه من أمراض مكة،\nفمن هنا لهنا أقنعوها ورجعوا فعلا به لبني سعد\n☆سبحان الله في الأول كانوا زاهدين فيه وأخذوه وهم مضطرين، دلوقتي هم إللي حريصين عليه وعايزينه معاهم\nبعد ما رجعوا بحوالي شهرين ثلاثة كده\nكان محمد ومعاه أخ له من الرضاعة وسط الأغنام وفجأة حليمة لقت الأخ جاي وعمال ينده عليها هي وزوجها وبيقول لها: إلحقوا أخويا القُرَشِي \nجاءه رجلان لابسين هدوم بيضاء وقّعوه في الأرض وفتحوا بطنه\nفبسرعة حليمة وزوجها الحارث راحوا يشوفوا إيه إللي حصل،\nأول ما وصلوا لقوا محمد الطفل إللي عمره سنتين وكم شهر واقف وشه متغير خايف ومصدوم من إللي حصل له\nفأبوه من الرضاعة سأله: إيه إللي حصل لك يابني\nفبدأ يحكي إللي حصل قال:\nجاءني رجلان لابسين ملابس بيضاء فواحد منهم صرعني، يعني وقعني في الأرض، وشق صدري وطلع قلبي،\nوأخرج من قلبي عَلَقة سوداء حاجة زي بذرة سوداء، وقال له: \nهذا حظ الشيطان منك\nفأخذ قلبه وغسله في طِست من ذهب مليان بماء زمزم يعني غسل قلبه في طبق كبير من الذهب مليان بماء زمزم،\nوبعدين رجع قلبه مكانه وخيّط صدره وسابوه ومشيوا\n☆إنتِ بتقولي إيه\nحادثة شق صدر محمد رسول الله  ﷺ ثابتة في صحيح مسلم\nتقدروا تقولوا إن رسول الله اتعمل له عملية قلب مفتوح من أكثر من ١٤٠٠ سنة \nمكنش في وجع مكنش في مخدر مكنش في غرفة عمليات معقمة،\nمكنش في نزيف مكنش...مكنش...\nإللي شق صدر رسول الله ﷺ كان جبريل عليه السلام بأمر من الله، \nالله إللي أمر النار إنها لا تحرق إبراهيم عليه السلام\nالله إللي أمر السكين إنها لا تذبح إسماعيل عليه السلام\nفهو هنا برده أمر الجسم إنه لا يشعر بأي ألم،\nوأمر الدم إنه لا ينزف، وأمر...وأمر... فهو إذا أراد شيئا إنما يقول له كن فيكون\n◇طيب ماهو ربنا كان قادر إنه يخلقه من غير ما تحصل القصة دي كلها أصلا، إيه لازمتها يعني\nشوفوا،\nربنا لا يفعل شيء إلا لحكمة\nخلينا كده نشوف بعض الحِكم من الحادثة دي\n◇أولا:\nتمهيد للطفل محمد ده إنك مش إنسان عادي..إنت بيحصل لك حاجات غريبة مختلفة..فاستعد\nولكم أن تتخيلوا مشاعر الطفل ده كانت عاملة إزاي ساعتها وهل ممكن إنه ينسى الحادثة دي في حياته\n◇ثانيا:\nتمهيد للناس إللي هيسمعوا ويعرفوا قصة محمد وإن الطفل ده له شأن في المستقبل فالناس تبدأ تركز معاه ويجذب انتباههم له\n◇ثالثا:\nالإيمان بالغيب..من صفات المؤمنين إللي هيدخلوا الجنة إنهم يؤمنون بالغيب،\nوقصص الأنبياء من الغيب والجنة والنار من الغيب،\nوالأحداث إللي حصلت لرسول الله ﷺ واحنا مشفنهاش من الغيب\nفلما تحصل حادثة زي كده ورسول الله ﷺ نفسه يحكيها ويقول عنها أنس بن مالك إنه شاف أثر الخياطة في صدر رسول الله ﷺ يبقى احنا لازم نؤمن بها من جُملة الإيمان بالغيب \nلأن إللي يؤمن بإن جبريل رفع قرية لوط بطرف جناحه لحد السماء وبعدين قلبها في الأرض،\nيصدق حادثة بسيطة زي شق صدر رسول الله ﷺ\nبعد ما سمعت حليمة السعدية وزوجها القصة من الطفل محمد خافوا ليكون الجن عملوا فيه حاجة\nفأخذوه ورجعوا لأمه عشان يرجعوه لها قبل ما يحصل له حاجة،\nفلما وصلوا عند آمنة قالوا لها :\nابنك أهه رجعنهولك خذيه ..وهو سليم قصادك واحنا كده أدينا الأمانة \nفطبعا آمنة شكت إن في حاجة ..إنتم لسه من كم شهر بس كنتم بتتحايلوا عليّ تاخدوه ..إيه إللي حصل\nفقالوا لها : مفيش حاجة ..احنا بس حبينا نرجعه لك وهو سليم\nفقالت :لأ..في حاجة\nوفضلت تضغط عليهم لحد ما حكوا لها إللي حصل\nفقالت لهم :خفتم عليه من الجن؟\nطيب خليني أحكي لكم إيه إللي حصل معايا يوم ما اتولد،\nوحكت لهم على النور إللي شافته يوم ما اتولد،\n وفي رواية إنها قالت يوم ما اتولد:\n\"أُعيذك بالله الواحد من شر كل حاسد\"\nفطمنتهم وقالت لهم متخافوش عليه، رجع الطفل محمد لأمه آمنة وعاش معاها، \nولما كان عمره ست سنين أخذته أمه آمنة عشان يزور أخواله في المدينة فماتت في الطريق واندفنت بين مكة والمدينة \nيعني الأول اتولد يتيم..وبعدين أمه ماتت وهو طفل صغير\nمتخيلين مشاعر طفل عنده ست سنين ماتت أمه\nفبدأ يهتم به ويرعاه جده عبد المطلب، \nوكان بيحبه جدا وكان بيعطف عليه عطف شديد مكنش بيعطفه على أبنائه،\nواحنا عارفين إن عبد المطلب كان رئيس مكة،\nفكان أبناؤه بيفرشوا لعبد المطلب فرش عشان يستقبل عليه الناس ويجلس معاهم ويسمع لمشاكل الناس،\nفمكنش حد يقدر يقعد على الفَرش ده قبل عبد المطلب لأنهم كانوا بيهابوه، كانوا يقعدوا يستنوه لحد ما ييجي وبعدين يقعدوا،\nالوحيد إللي كَسر القاعدة دي كان الطفل محمد \nكان يقعد عادي ولما كان أعمامه يحاولوا يقوّموه ويبعدوه،\nكان عبد المطلب بيقول لهم سيبوه..ابني ده له شأن في المستقبل\nوكان بيعجبه جدا كل إللي حفيده بيعمله، زي كده لما يكون في جد أو جدة مدلعين أحفادهم ويدافعوا عنهم،\nوطبعا الأطفال تلاقيهم بيحبوهم جدا\nالشاهد إن عبد المطلب كان بيحب حفيده محمد جدا وكان بيحنو عليه كثيرا عشان يعوضه عن يُتمه،\nوأكيد الطفل محمد كان حاسس بكده وكان بيحبه هو كمان،\nوطبعا وجوده مع عبد المطلب خلّاه يتعلم إزاي يتعامل مع السادة وكبراء الناس،\nويشوف مشاكل ده ومشاكل ده وإزاي جده كان بيتعامل بكل حكمة مع المشاكل، فأخذ خبرة واسعة جدا \nلما وصل عمره لثمان سنين..مات جده عبد المطلب\nمتخيلين طفل عمّال يتنقل من شخص لشخص، وكل شوية يفقد حد بيحبه ويهتم به،\nبيحصل له صدمة نفسية واحدة ورا الثانية وهو صغير،\nتعتقدوا إن طفل زي ده عقليته ونُضجه هيبقى زي غيره من الأطفال إللي عاشوا حياة طبيعية\nطبعا لأ\nده طفل ذاق معنى الألم ومعنى الفِراق، فقلبه هيكون أرق وأحن من غيره\nكان عبد المطلب وصّى ابنه عبد مناف إللي هو لقبه أبو طالب إنه ياخد باله من محمد ابن أخيه ويراعيه،\nفلما مات عبد المطلب تولى رعاية الطفل محمد عمه أبو طالب لما كان عمره ثمان سنين.\n《البداية والنهاية لابن كثير》\nأبو طالب كان فقير وكان عنده عيال كثيرة، \nمع إنه كان سيد وشريف في مكة لكنه كان فقير، ومع كثرة عياله الوضع كان صعب\nفكان لما بيحطوا الأكل مثلا لأبنائه عشان يأكلوا كانوا بيهجموا على الأكل..فكان الطفل محمد من أدبه إنه مكنش بيهجم معاهم،\nكان بيستناهم يخلصوا ولو اتبقى حاجة بياكلها متبقاش مكنش بياكل ومكنش بيقول إنه جعان\nواستمر الموضوع ده فترة لحد ما عمه أخذ باله فقال لأهل بيته خلّوا لمحمد أكل لوحده على جنب لأنه مش بياكل مع الأولاد،\nعاش محمد مع أبو طالب في بيته، وفي يوم من الأيام لما كان عمره اثنا عشرة سنة، أبو طالب كان خارج للتجارة في بلاد الشام،\n فمحمد كان عايز يروح معاه فأعمامه وعماته رفضوا وقالوا إنت كده هتعرضه للأمراض وهو صغير والسفر طويل،\nفقال خلاص مش هاخده.. فلقى محمد بيبكي فقلبه رق له، وقال : والله لأخذك معي ومش هفارقك ولا تفارقني أبدا\nوفعلا أخذه أبو طالب وانطلقوا في الرحلة إلى الشام وهم في الطريق .....يا ترى حصل إيييه\nهنعرف إن شاء الله الجزء الجاي\n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_السادسة\n#مصير_أب_وأم_وجد_النبي\n#حلف_الفضول\nكنا واقفين المرة إللي فاتت عند أبو طالب لما كان عايز يسافر للشام وبعدين ابن أخوه محمد كان عايز يروح معاه وأعمامه وعماته رفضوا،\nفلما بكى محمد قلب أبو طالب رقّ له فقال له:\nوالله لن أفارقك ولن تفارقني، وأخذه معاه فعلا وبدأوا رحلتهم إلى الشام\n☆سؤال،\nإزاي أبو طالب بيحلف بالله وهو كافر\nوكمان عبد المطلب مش كان كافر.. إزاى يقول الله أكبر وإزاى سمى ابنه عبدالله\nوإزاى نَذر لله، وكمان وعارف إن ربنا اللى بيرزق وكمان صمم إنه يوفِي بالنذر وكان هيذبح أحب ابناءه ولما اتولد حفيده سماه محمد وكان نفسه إنه يطلع هو النبى معنى كده إنه مصدق إن فى نبى وفى ربنا وكمان قال للبيت رب يحميه\nاحنا قلنا قبل كده في قصص الأنبياء إن الكفار والمشركين بصفة عامة كانوا بيؤمنوا بتوحيد الربوبية وبيكفروا بتوحيد الألوهية،\nتوحيد الربوبية معناه إن الكون ده له رب والرب يعني مالك كل شيء وهو الخالق وهو المُحيي والمميت وهو النافع والضار،\nوربنا بيقول عن الكفار:\n\"وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ لَيَقُولُنَّ اللَّهُ ۚ\"\nفهمّ كانوا مؤمنين بإن الكون ده له خالق لكن مكنوش معترفين بوحدانية الإله الخالق ده، كانوا معتقدين إن الرب ده معاه شركاء بيساعدوه.\nومعنى الرب غير معنى الإله\nلأن الإله معناه هو من يستحق العبادة، وأي عبادة بنعملها من صلاة أو ذكر أو ذل أو خشوع أو نذر تكون لله 《وبس》\nوده اسمه توحيد الألوهية،\nعشان كده إحنا بنقول لا إله إلا الله إللي هي كلمة التوحيد، يعني كأننا بنقول مفيش حد يستحق العبادة غيرك يا الله\nفحتى لما عبد المطلب كان عايز يذبح ابنه عبد الله راح يذبحه عند الصنم إساف عشان يوفي بنذره\nفالشرك واضح فيهم وفي أفعالهم، \nوكمان كان في بواقي من دين إبراهيم عليه السلام زي الحج بأركانه،\nأيوة حصل فيه تحريف لكن لسه في بقايا من الدين وكمان دين إبراهيم كان مشهور بين العرب لكن مكنوش يعرفوا إزاي يتبعوا الدين ده\n◇طيب هل معنى كده إن عبد المطلب جد النبي وأبوه وأمه كانوا على دين إبراهيم عليه السلام، ولّا كانوا مشركين ومصيرهم إلى النار\nخلونا نشوف إيه هو مصير أمه وأبيه وجده ﷺ\nلأن في ناس زي الشيعة والصوفية وغيرهم بيقولوا إن أم وأب وجد رسول الله من أهل الجنة وده كلام غير صحيح\nلأنه مخالف لكلام رسول الله ﷺ وكلام القرآن\n◇أولا أبوه:\nهو من أهل النار؛ لأنه كان بيعبد الأصنام، وجاء رجل من الأعراب يسأل رسول الله ﷺ عن أبيه وبيقول له:\nأين أبي؟...فقال له رسول الله ﷺ: أبي وأبوك في النار.\nفأبو النبي ﷺ إما إنه وصلت له الرسالة بطريقة معينة ورفض إنه يتبع،\nأو إنه من أهل الفترة فيوم القيامة هيعصي الله في الإختبار ويدخل النار، وطبعا الكلام ده كله بوحي..يعني ربنا هو إللي أخبر رسوله عن مصير أبيه \n◇ثانيا أمه:\nهي من أهل النار؛ لأن رسول الله ﷺ قال في الحديث استأذنت ربي أن أزور قبر أمي فأذن لي، واستأذنته أن استغفر لها فلم يأذن لي،\nقال تعالى:\n\"مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَن يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَىٰ مِن بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ\"\nوالحديث بتاع إن ربنا أحيا والدا رسول الله ﷺ فدعاهم للإسلام فآمنا به حديث موضوع لا يصح،\nوخصوصا إن الحديث مُخالف لآيات القرآن والأحاديث الصحيحة \n◇والحديث الموضوع معناه إن حد اخترعه وقال إن رسول الله ﷺ قاله.\n◇ثالثا جده عبد المطلب:\nالعلماء اختلفوا فيه:\n¤علماء قالوا إنه من أهل الفترة...\n◇وأهل الفترة يعني الناس إللي موصلهمش رسالة الإسلام من أي رسول، ودول وضعهم مختلف، لأن لسه هيكون لهم امتحان في الآخرة ،\nففي يوم القيامة ربنا هيجيب جزء من النار ويقولهم: إنتم مجالكوش رسول فاليوم أنا رسول نفسي، ادخلوا في النار دي، فلو سمعوا الكلام هيدخلوا الجنة، ولو رفضوا ربنا هيقولهم: \nأنتم لرسلي أشد تكذيبا..يعني في وسط الأهوال دي وبقولكم ادخلوا النار ومسمعتوش كلامي أمّال في الدنيا كنتم هتعملوا إيه،ويكون مصيرهم النار \n¤وعلماء قالوا إنه من أهل النار لأنه كان بيعبد الأصنام وكان وصل له دين إبراهيم عليه السلام،\nوكان في نصارى في مكة على دين عيسى عليه السلام،\nزي ورقة بن نوفل، وكان في ناس موحدين زي زيد بن عمرو بن نفيل،\nوهنعرف قصتهم بعدين إن شاء الله \n¤طيب خلونا نفترض جدلا كده ..مجرد افتراض\nإن أم رسول الله وأبوه وجده من أهل الفترة وموصلتهمش الرسالة.. هل ينفع إننا نقول عليهم إنهم من أهل الجنة \nطبعا لا يجوز \nلأننا منعرفش أهل الفترة دول مصيرهم هيكون إيه أصلا ..لأن لسه لهم اختبار في الآخرة \nفيكون معاملة أهل الجاهلية معاملة الكفار في الدنيا، \nيعني لا ندعوا لهم ولا نستغفر لهم؛ لأن ظاهرهم إنهم ماتوا على الكفر،\nويوم القيامة ربنا هو إللي يَفصل فيهم وهو أعلم بهم، \nإذا كانوا فعلا وصلت لهم الرسالة ولا لأ\n◇زي مثلا لما واحد من الكفار يموت في زماننا دلوقتي،\nوتيجي واحدة تقولك إيه المشكلة لما أقول الله يرحمه مش يمكن مات على الإسلام واحنا منعرفش\nمنقدرش ندعو له بالرحمة لأن هو ظاهره إنه مات على الكفر،\nوربنا نهانا إننا ندعو لأي حد ظاهره الكفر\nحتى أهل الفترة وأي أحد لم تصل له رسالة الإسلام في زماننا منقدرش ندعي له بالرحمة\nخدوا بالكم بقى من نقطة مهمة\nإن لو مثلا واحدة نصرانية أو يهودية أو أي حد كافر مات قصادك على الكفر لا يجوز إنك تقولي إن فلانة دي في النار\nيعني احنا بنقول يا جماعة أي حد هيموت على غير ملة الإسلام هو في النار، لااااكن مينفعش نيجي على شخص بعيييينه ونقول 《فلانة 》 دي في النار \nفالإسلام إللي قال لك متدعيش بالرحمة لأي حد ظاهره إنه مات على الكفر،\nقال لك برده متحكمش على شخص 《معين》 بالاسم كده إنه هيدخل جنة أو نار إلا بوحي\nده كان بالنسبة للكفار...فما بالكم بقى بواحد مسلم ظاهره الإسلام\nعشان بس الناس إللي بتقعد تقول فلان ده كافر، وإللي بتهزر مع صاحبتها وتقول لها يا كافرة،  \nولّا إللي يقعد يقول فلان ده في النار ولا فلان ده في الجنة،\nكل ده لا يجوز يا جماعة...دي عقيدتنا احنا المسلمين ، اتعلموها عشان الناس إللي بتشوه الإسلام بسبب كلامهم وهمّ مش عارفين حاجة\nأنا فصّلت الموضوع من البداية عشان مش هرجع له تاني،\nلأن دي أكيد حاجة بتؤذي رسول الله ﷺ وأنا قلتها لأنها داخلة في العقيدة فكان لازم نعرفها\nنرجع لأبو طالب وابن أخيه محمد بعد ما خرجوا للتجارة في الشام،\nفي الطريق كان في صَوْمعة لراهب من رهبان النصارى يُقال إن اسمه بُحيرى، \nواحنا قلنا معنى صومعة قبل كده\nلما كانت قوافل التجارة بتعدي على الصومعة بتاعته مكنش بيهتم بهم وحتى لو حد أتى له يكلمه مكنش بيرد عليهم،\nلكن القافلة دي لاحظ بُحيرى إن فيها حاجة غريبة\nشاف إن في سحابة بتظلل القافلة دي وهي ماشية،\nوشاف الحجر والشجر بيسجد للقافلة وهي ماشية،\nوشاف إنهم لما نزلوا تحت الشجرة بيرتاحوا لقى الشجر بتميل أغصانها عشان تظلل الناس إللي نزلوا يقعدوا تحتها\n☆الحجر والشجر بيسجدوا إزاي يعني\nممكن تكون بميلها أو تحركها أو بطريقة تانية احنا منعرفهاش \nزي ما ربنا قال عن سجود الكون لله تعالى وتسبيحه بحمده: \n\"وَإِن مِّن شَيْءٍ إِلاَّ يُسَبِّحُ بِحَمْدَهِ وَلَكِن لاَّ تَفْقَهُونَ تَسْبِيحَهُمْ\"\nوقال: \n\"وَلِلّهِ يَسْجُدُ مَن فِي السَّمَاوَاتِ وَالأَرْضِ طَوْعًا وَكَرْهًا وَظِلالُهُم بِالْغُدُوِّ وَالآصَالِ\"\nالمهم،\nاستغرب بُحيرى وقال القافلة دي فيها حاجة غريبة،\nفعمل أكل وراح للقافلة إللي فيها ابو طالب وابن أخيه محمد وقال لهم تعالوا كلوا،\nفاستغربوا منه هو كمان..أول مرة يعمل معاهم كده، فقالوا له :\nإنت أكيد وراك حاجة ...إيه التغير ده\n \nفالمهم كلهم راحوا عشان يأكلوا ماعدا محمد سابوه في القافلة عشان سنه صغير فمش هيقعّدوه مع راهب كبير زي بحيرى ومع الناس الكبار،\nزي لما بيكون في اجتماع في العائلة للناس الكبيرة في السن   وبعدين نقول للعيال الصغيرين روحوا إلعبوا\nفسابوه فعلا وراحوا يأكلوا...فبُحيرى قعد يتأمل فيهم ويشوف تصرفاتهم يمكن يلاقي إللي بيدور عليه..لكنه ملقاش حاجة مميزة في الناس دي فسألهم:\nإنتم كل إللي في القافلة ؟ يعني مفيش حد مجاش معاكم\nفقالوا لبعض: تصوروا احنا قوم لئام \nاحنا جئنا نأكل وسيبنا اليتيم لوحده هو إللي يحرس القافلة،\nفراحوا جابوا محمد عشان يأكل معاهم،\nأول ما شافه بُحيرى قعد يبص له جامد ويركز في تصرفاته فعرف إنه هو ده الشخص إللي الشجر والحجر سجد له\nفقال له بُحيرى:\nيا غلام أسألك باللات والعزى إنك تجاوبني على كل إللي هسألك عنه\n☆بحيرى لا يؤمن باللات والعزى، بس هو سمع الناس بيقولها  لبعض فكان بيقلدهم بس على أساس إن محمد زيهم يعني فبيحلّفه\nالمفاجأة بقى إن محمد إللي عنده اثنا عشر عام قال له:\nمتحلفنيش باللات والعزى..أنا مش بكره حاجة أد ما بكرههم\n \nفبُحيرى قال له: \nطيب أسالك بالله إنك تجاوبني على الحاجات إللي هسألك عنها\nفقال له محمد: إسأل إللي إنت عايزه.\nفقعد يسأله عن صفة نومه وأكله وشربه وبيحلم بإيه فكل ما يسأله عن حاجة ويجاوب يلاقي الإجابة بتاعته هي نفس الوصف بتاع آخر نبي هيظهر\nفطلب بحيرى إنه يشوف ظهر محمد، فلما كشف عن ظهره شاف 《خاتم النبوة》 \n☆خاتم النبوة عبارة عن جزء بارز من الجسم بين الكتفين بنفس لون الجلد في حجم بيضة الحمامة،\nحواليه حبات الخال وعليه شعرات متجمعات ، وحبة الخال إللي هي الشامة.. يعني نقطة بتكون لونها مائل للسواد كده\nوخاتم النبوة مكنش مكتوب عليه أي حاجة خالص\nلا لفظ جلالة ولا اسم محمد ولا أي حاجة \nفكده بحيرى اتأكد إن الغلام محمد ده هو نبي آخر الزمان \nسأل بُحيرى مين وليّ الولد ده؟\nفقال ابو طالب : أنا أبوه\n.. يقصد يعني إن محمد تحت كفالته\nفقال له بُحيرى : لأ إنت مش أبوه.. لا ينبغي أن يكون أبوه حي\nفقال له : أنا عمه\nفقال له : ابن أخوك ده هيكون له شأن عظيم في المستقبل،\nخذه وارجع به لمكة...وخد بالك من اليهود لأنهم لو شافوه وعرفوا إللي أنا عرفته منه مش هسيبوه وهيؤذوه\nفخاف أبو طالب على ابن أخيه فبعث معاه حد يرجعه مكة وكمل هو في رحلته للشام.\n《القصة صحيحة موجودة في البداية والنهاية لابن كثير بأحاديث صحيحة...لكن اسم الراهب بُحيرى ليس عليه دليل لكن أهل التاريخ ذكروا اسمه》\nعاش محمد مع عمه أبو طالب وأول ما وصل عمره لخمسة عشرة سنة بدأ يشتغل عشان يساعد عمه الفقير، \nفاشتغل برعي الغنم...وطبعا رعي الغنم مش شغلانة سهلة؛\n لأنها محتاجة صبر، لأن الغنم بيروح هنا وبيروح هنا فبيجري ورا دي وبيروح يجيب دي، \nفاتعلم الصبر من وهو في سن المراهقة زي ما بنقول، والسن ده أصلا تلاقي فيه الشباب مندفعين ومعندهمش صبر\nفكان صبور وكان صادق لم يكذب أبدا\nأصلا الكذب عند الناس في الجاهلية حاجة عيب جدا، فكان صفة الصدق منتشرة وصفة الوفاء بالعهد،\nوكان أمين جدا ومكنش بيقول أي كلام فاحش ، فكل الصفات دي اكتملت في أخلاق الشاب محمد، ومن الحاجات إللي تميز بها إنه لم يعبد الأصنام أبدا\nمع إن قومه كلهم بيعبدوا الأصنام وعايش في وسط أهله إللي بيعبدوا الأصنام ومع ذلك كان بيكرهها وعمره ما عبدها\nوحتى الأمور إللي تعتبر عادية بين أهل مكة ربنا عصمه منها،\nيعني عمره ما حضر عرس فيه أغاني ومزامير أبدا،\nحتى لما كان عايز يروح عرس لما راح العرس ربنا خلاه ينام ومصحيش غير تاني يوم \nلما وصل عمره عشرين سنة حصلت حادثة في مكة،\nوهي إن واحد من التجار جاء مكة عشان يبيع بضاعته، فاشتراها منه العاص بن وائل، لكن مدفعش الفلوس وقعد يماطل في دفع الفلوس،\nلحد ما العاص بن وائل قال للتاجر: ملكش حاجة عندي واعمل إللي تعمله\nفراح التاجر واقف عند الكعبة وقعد ينشد شعر بيقول فيه لأهل المكة أنا هفضحكم في العرب إنكم أخذتم أموالي وظلمتوني \nفسمع الكلام الزبير بن عبد المطلب فجمع أشراف الناس واتفقوا إنهم هيعملوا حِلف ينصروا فيه المظلوم،\nيعني يكون مجموعة من الناس تتفق على إن أي مظلوم يرجعوا له حقه،\nفكان من ضمن الناس إللي اشتركت في الحِلف ده محمد بن عبد الله لما كان عمره عشرين سنة،\nوفعلا رجعوا للرجل حقه وأي أحد مظلوم كانوا بيرجعوا له حقه،\nوالحلف ده قال عنه رسول الله ﷺ بعدين: دُعيت لحلف في الجاهلية لو دُعيت له في الإسلام هشترك فيه \nإللي هو حلف الفضول، \nلأن هو قائم على أهداف نبيلة وهي نصرة المظلوم،\nوعلى فكرة نصرة المظلوم مش بس للمسلم لكن لأي أحد مظلوم\nلدرجة إن لو مسلم ظلم غير مسلم نقتص لغير المسلم من المسلم، مش عشان مسلم يبقى خلاص\nالإسلام لا يرضى بالظلم لمسلم أو غير مسلم\nاشتهر الشاب محمد بين أهل قريش بالصدق والأمانة والأخلاق العظيمة جدا، مين إللي سمعت عنه؟\nامرأة اسمها خديجة بنت خويلد\nياترى إيه قصته مع خديجة؟\nده إللي هنعرفه الجزء الجاي إن شاء الله\nالجزء الي   بعده هنا"}, {"n": 44, "l": "الجزء السابع | زواجه من خديجه | حادثة وضع الحجر الأسود | .. | والحلقه الثامنه | نزول الوحي", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_السابعة\n#زواجه_من_خديجة\n#حادثة_وضع_الحجر_الأسود\nاتكلمنا المرة إللي فاتت عن الشاب محمد لما كان عنده عشرين عام واشترك في حِلف الفضول عشان ينصر المظلوم،\nواتكلمنا عن أخلاقه وإزاي كان صادق وعمره ما كذب ولو مرة واحدة،\nوقلنا إنه كان أمين جدا وبيحافظ على عهوده، ومكنش بيعمل الحاجات إللي الشباب في سنه عادة بيعملوها ومعروف بين الناس إنهم بيعملوها،\nفكان الناس بتحبه جدا بسبب أخلاقه دي لدرجة إنهم كانوا مسميينه 《الصادق الأمين》،\nكان بيشتغل في رعي الغنم زي ما قلنا وبعدين بدأ يشتغل في التجارة، \nكان في مكة امرأة أرملة يعني مات عنها زوجها...ذكية... حازمة، غنية عندها تجارة واسعة اسمها:\n 《خديجة بنت خُوَيلد》\nكان عمرها أربعين سنة، وكان سادات مكة نفسهم يتزوجوها لكن هي مكنتش بترضى، \nكانت بتستأجر الرجال عشان يأخذوا بضاعتها ويتاجروا فيها وتديهم أجر زي مرتب كده،\nمقابل إنهم يشغّلوا لها فلوسها، فهي مكنتش بتخرج للتجارة بنفسها 《إطلااااقا》 \nسمعت خديجة عن الشاب محمد وعن صدقه وأمانته وأخلاقه، فحبت إنها تستأجره عشان يشتغل لها في أموالها،\nفبعتت له حد يقول له إن خديجة عايزاك تشتغل عندها مقابل مبلغ من المال،\nفوافق الشاب محمد وخرج بتجارة خديجة، ونظام التجارة إنهم يأخذوا البضائع من مكة مثلا ويروحوا يبيعوها في مكان تاني،\nفأخذ الشاب محمد بضائع خديجة وخرج من مكة عشان يتاجر وكان معاه في الرحلة دي غلام لخديجة اسمه مَيْسرة...عبد يعني \nميسرة وهو في الرحلة مع الشاب محمد شاف حاجات عجيبة\nوهم ماشيين في الطريق مثلا شايف إن في سحابة ماشية معاهم بتظللهم من الشمس\nولما وصلوا مدينة بُصرى في الشام كان في شجرة بعيدة كده راح الشاب محمد وقعد تحتها،\nفكان في راهب من رهبان النصارى موجود في المكان ده فسأل ميسرة مين الشاب ده\nفميسرة قال له: ده محمد شاب من قريش ..في إيه يعني\nفالراهب قال لميسرة : الشجرة إللي هو قاعد تحتها دي محدش بيقعد تحتها غير الأنبياء \nفميسرة استغرب طبعا.. نبي \nده غير بقى إللي شافه من أخلاقه، يعني هو كان سمع عنه لكن لما شاف بعينه بقى كان الوضع حاجة تانية،\nانبهر بأخلاقه جدا وخصوصا لما شافه وهو بيتعامل مع الناس وهو بيبيع ويشتري \nولقى الناس نفسهم بيُقبلوا عليه ويشتروا منه بسبب أخلاقه،\nومش بس كده ده عمل حاجة محدش غيره من التجار عملها،\nالتجار كانوا بيروحوا يبيعوا البضاعة ويرجعوا،\nهو بقى بعد ما باع البضاعة اشترى بضاعة تانية ولما رجع مكة باع البضاعة الجديد فكسب مرتين\nفالمكسب إللي رجّعه لخديجة مع أمانته طبعا كان أكثر واحد جاب لخديجة مكسب،\nفخديجة تفاجأت لما شافت الفلوس إللي كسبتها وكمان ميسرة حكى لها إللي شافه وسمعه فانبهرت به خديجة وأُعجبت به جدا\nفكان لها صاحبة اسمها نفيسة كلمتها وقالت لها إنها تروح لمحمد وتعرض عليه إنه يتزوج خديجة،\nفوافق الشاب محمد إنه يتزوجها فعلا..حد يطول يتزوج خديجة إللي كل سادات قريش نفسهم يتزوجوها وهي رافضاهم\nكان عمره في الوقت ده خمسة وعشرين سنة وخديجة كان عمرها أربعين سنة...يعني الفرق بينهم خمسة عشرة سنة على أرجح الأقوال لأن مفيش حديث ثابت صحيح بتحديد السن بالضبط\n☆في أقوال ثانية بتقول إن خديجة لما تزوجت من رسول الله كان عمرها خمسة وثلاثين أو ثمانية وعشرين سنة.\nالمهم راح الشاب محمد لأعمامه وقال لهم الموضوع فراح معاه عمه أبو طالب وحمزة ابنا عبد المطلب عشان يخطبوها من وليّها..يُقال عمها ويقال من أخوها ويُقال من أبوها، المهم إنه خطبها وتزوجها \nودفع لها مهر عشرين ناقة وده كان مبلغ وقدره... مش حاجة بسيطة \nبعد ما تزوجت خديجة بالشاب محمد سلّمت كل تجارتها له عشان هو إللي يديرها\n☆وده معناه إن خديجة بنت خويلد لم تعمل خارج البيت لا قبل زواجها ولا بعده \nمسمعش حد يقول بقى ما السيدة خديجة زوجة الرسول كانت بتعمل بالتجارة\nويقول عادي النساء تسيب بيتها والمهمة إللي ربنا أعطاها لها وتخرج تشتغل وسط الرجال وتختلط بهم وتبقى سيدة اعمال وتسافر هنا وهنا \nسامعاكي يا حبيبتي ياللي هتقولي يعني نقعد في البيت ومنشتغلش\nطيب ماحنا محتاجين الدكتورة والممرضة و...و...\nأنا مقلتش كده ..أيوة احنا محتاجين ده ومحدش قال عكس كده،\nلكن الكلام للناس إللي بتحتج بعمل خديجة رضي الله عنها في التجارة وبيقولوا عادي المرأة تختلط بالرجل،\nوتسيب بيتها وعيالها وتطلع تشتغل شغل مش بتاعها أصلا\nلأن عمل المرأة له ضوابط وشروط مش موضوعنا هنا\nوحتى لو افترضنا جدلا ...مجرد افتراض كده إن السيدة خديجة كانت بتعمل بنفسها في التجارة فده كان قبل الإسلام وقبل الهجرة أساسا،\nوآية الحجاب والقرار في البيت نزلت في السنة السادسة من الهجرة والسيدة خديجة ماتت قبل الهجرة بثلاث سنين\nعاشت خديجة بنت خويلد مع الشاب محمد الصادق الأمين إللي اتولد يتيم وأمه ماتت وهو صغير حتى جده إللي كان بيحبه جدا مات وهو صغير وعمه كان مشغول بعياله وتجارته،\nفمكنش في حد يربيه أو يهتم به زي ماحنا بنهتم بعيالنا كده  ومع ذلك كان صاحب أخلاق عالية جدا\n☆ودي رسالة لنا إن ربنا هو إللي بيربي..ربنا هو إللي له الفضل، ربنا هو إللي بيحفظ ..حتى لو الإنسان اتولد يتيم ملوش حد في الدنيا فهو يقدر يربي نفسه ويعلم نفسه مع الإستعانة بالله\nكانت خديجة أول زوجة يتزوجها الشاب محمد وعاش معها،  وولدت له أول أبنائه واسمه القاسم، وكان الناس بيقولوا له أبو القاسم،\nفتخيلوا فرحة أول طفل وكمان ولد وكان عادة العرب إنهم بيفضّلوا الأولاد على البنات لدرجة إن في ناس منهم لو اتولدت له بنت كان بياخدها ويدفنها حية\nطبعا مكنش كل العرب كده،  وإلا لو كان ده ظاهرة منتشرة كان زمان الناس انقرضت..هيتزوجوا ويخلفوا إزاي\nلكن طبعا حد بأخلاق الشاب محمد عمره ما يفكر التفكير ده \nبعد ما ابنه القاسم كِبر حوالي سبعة عشر شهرا يعني سنة ونص وقيل سنتين يعني زحف وبدأ يمشي وينطق كلماته الأولى ،\nوانتم عارفين الأطفال في السن ده بيكونوا الأباء متعلقين بيهم أد إيه \nبعد ما وصل للسن ده...مات\nابنه إللي لعب معاه وإللي كان بيشيله ويحضنه وكان بيحبه وبيخاف عليه وياخد باله منه ويهتم به ويضحك معاه على كلماته الأولى...مات\nهو مجرد أب...بشر ... وزوجته خديجة أم لهم مشاعر زينا بالضبط،\nتخيلوا مشاعرهم كانت إيه لما ابنهم مات،\nمش احنا بس إللي بنحزن ومش احنا بس إللي بنتألم..الشاب محمد وزوجته زينا حزنوا وتألموا ..لكن الحياة بتمشي\nبعدها حملت خديجة وأنجبت بنت سموها زينب،\nوبعدها بثلاث سنوات تقريبا أنجبت خديجة بنت تانية سموها رقية وبعدها بحوالي سنة أنجبت البنت الثالثة وكان اسمها أم كلثوم، \nوبعدها بسنة أنجبت خديجة آخر بناتها واسمها فاطمة،\nوكان عمر أبوها في الوقت ده خمسة وثلاثين سنة\nفي الوقت ده حصلت حادثة في مكة\nوهي إن الكعبة جدرانها بدأت تتشقق وبدأ يقع منها طوب، وكانت زي ما هي من ساعة ما بناها إبراهيم عليه السلام، يعني بقالها مئات السنين ...متخيلين من زمن إبراهيم \nفاجتمع أهل امكة وقالوا :\nإنتم شايفين الكعبة بيحصل فيها إيه..عمالة بتقع ودي بيت الله إزاي نسيبها كده\nفقالوا لبعض طيب نعمل إيه\nقالوا خلاص نحاول نرممها ونصلحها، فقال لهم واحد من سادات قريش اسمه 《الوليد بن المغيرة》 لو كان واحد فيكم عنده بيت ووقع منه أجزاء هيعمل فيه إيه،\nهيرممه ولا يهده ويبنيه من الأول تاني ؟ \nقالوا يهده ويبنيه\nقال لهم خلاص احنا نهد الكعبة ونبنيها مرة تانية \nطبعا كل إللي قاعدين شافوا إللي حصل لأبرهة \nفبصوا لبعض  وقالوا: نهدمها ؟!!!\nنهدم إييييه\nإنت ناسي إللي حصل لأبرهة لما بس فكر إنه يهدم الكعبة\nإنت عايز يحصل لنا زي إللي حصل له\nفقال لهم : احنا هندمها عشان نبنيها، لكن أبرهة كان عايز يهدمها احتقار لها \nفقالوا له: إنت صاحب الفكرة ..ابدأ إنت الأول\nوفعلا بدأ الوليد بن المغيرة في هدم الكعبة وهم بيتفرجوا عليه هيحصل له إيه\nفبعد ما بدأ يهدم في الكعبة قال لهم: تعالوا ساعدوني\nقالوا له: لاااا \nلحد ما نشوفك بكرة ..لو محصلكش حاجة هنساعدك، حصل لك حاجة هنرجع كل حاجة زي مكانها\nفجه تاني يوم سليم مفهوش أي حاجة وبدأ يشتغل في هدم الكعبة فاطمنوا وبدأوا يهدموا معاه \n أهل مكة قالوا ده بيت الله مينفعش يدخل فيه مال حرام\nفاحنا هنبنيها بالمال الحلال فقط يعني مندخلش فيها مال ربا...ومندخلش فيها مهر بغي يعني فلوس دعارة أو فلوس مأخوذة من ناس بالباطل وهكذا،\n☆احنا قبل كده إن معظم الناس كانوا مؤمنين بتوحيد الربوبية يعني الكون له رب يعني له خالق عشان بس محدش يتوه في النص\nفجمعوا الفلوس الحلال لقوها قليلة مش هتكفي \nفقالوا نبنيها ناقصة ولا إننا نحط في بيت ربنا مال حرام\n◇طبعا لا تعليق\nفبنوها ناقصة فعلا فبدل ما يعملوها ببابين باب للدخول وباب للخروج عملوها بباب واحد،\nوباب الكعبة كان واصل للأرض وهم رفعوه عن الأرض عشان يدخلوا الكعبة الناس إللي هم عايزينهم بس\nوسابوا جزء مش مبني بس حطوا عنده علامة وهو كما يسمى اليوم حِجر إسماعيل الحتة إللي عند الكعبة إللي عاملة زي القوس دي\n  )\nفالمفروض إن الجزء ده كان يدخل في الكعبة لكن عشان الفلوس مكفتش فسابوها على كده \nالمهم بعد ما خلصوا اتبقى آخر حاجة وهي:\n مين إللي هيحط الحجر الأسود مكانه \nهم كانوا متعاونين وبيساعدوا بعض طول فترة بناء الكعبة،\nدلوقتي آخر حاجة هتتعمل ..واحد بس إللي هيعملها، \nفاتخانقوا\nكل واحد من القبائل بيقول احنا إللي نحط الحجر الأسود مكانه\nطبعا شرف مش هيتكرر تاني \nوصل الموضوع إنهم هيحاربوا بعض \nفكان في واحد من المعمرين كبار السن يعني عمره طويل،\nقال لهم: شوفوا، خلونا نحكّم أول واحد يدخل من باب البيت الحرام،\nفقعدوا يستنوا وفجأة لقوا داخل عليهم رجل،\nراحوا كوووولهم قالوا في نفس واحد: \n《الصادق الأمين..رضينا..رضينا 》\n☆احفظوا الجملة دي كويس أوي \nعشان تعرفوا الناس دي هتعمل إيه بعدين مع الصادق الأمين إللي رضيوا حكمه ده \nطبعا هو دخل مش عارف حاجة\nإيه يا جماعة في إيه؟\nفحكوا له إللي حصل فراح قالع ردائه زي عباية كده بتتلبس عالكتف وقال لهم: \nكل واحد يمسك بطرف الرداء ..فمسك كل واحد منهم بطرف الثوب بتاعه وراح 《الصادق الأمين》أخذ الحجر الأسود من مكانه وحطه على الثوب بتاعه، \nوقال لهم:\n امشوا به لحد ما نوصل لمكان وضع الحجر، فلما وصل للمكان بتاعه راح 《الصادق الأمين》 واخد الحجر ووضعه في مكانه المعروف لحد دلوقتي،\nفكان إللي وضع الحجر الاسود في مكانه هو\n《 الصادق الأمين محمد بن عبد الله بن عبد المطلب》\nوالناس اتبسطت والمشكلة اتحلت في ثواني\nوإلا كانت هتقوم حرب بين أهل مكة ويفنوا بعضهم\nقبل ما يبلغ محمد بن عبد الله عمر الأربعين سنة،\nلما كان بينام ويشوف رؤيا كانت بتحصل بالضبط زي ما شافها في الرؤيا بالضبط\nيعني تخيل كده إنك شفت رؤيا وبعد ما صحيت وبتقضي يومك عادي لقيت إللي شوفته في الرؤيا بيحصل قصادك\nومش مرة ولا مرتين...\nده أي رؤيا تشوفها بتحصل وبتحقق بالضبط وأول ما تصحى..تخيل إحساسك هيبقى عامل إزاي\nوكان لما يمشي في مكان لوحده يسمع حد من وراه بيقول: السلام عليك يا رسول الله...فكان يبص وراه ميلاقيش حد\nخدوا بالكم هو مجرد بشر زينا بالضبط\nبيخاف..بيتألم..بيحزن..فلكم أن تتخيلوا واحد كل ما يمشي يسمع صوت من وراه ويبص ميلاقيش حد \nيعني الواحد لما بيكون لوحده وسمع صوت حاجة وقعت في المطبخ ولا أي صوت من هنا ولا من هنا بيبقى هيموت من الرعب \nفأنا عايزاكم تتخيلوا مشاعره كانت عاملة إزاي في موقف زي كده\nلا ولسه كمان لما \n......لما إيييه \nنكمل الجزء الجاي إن شاء الله \n#قصص_الانبياء(٢)\n#السيرة_النبوية_إيمان_شلبي\n#الحلقة_الثامنة\n#نزول_الوحي\nوقفنا المرة إللي فاتت عند محمد بن عبد الله لما كان بينام ويشوف رؤيا ويلاقيها اتحققت أول ما يصحى من النوم زي ما شافها بالضبط،\nوقلنا إنه كان بيمشي في الطريق فيسمع صوت من وراه بيقول: \nالسلام عليك يارسول الله ولما كان يبص واره مكنش بيلاقي حد فمكنش عارف إيه الصوت ده،\nكان في الفترة دي بيحب يختلي بنفسه، يعني يكون لوحده يتعبد، واحنا قلنا إنه مكنش بيعبد الأصنام؛ لأنه كان عارف بفطرته إن في إله للكون ده،\nوخلال سنين حياته والأحداث إللي حصلت له من حادثة شق الصدر، ده غير إن الأنبياء بصفة عامة معصومين من الشرك قبل الرسالة زي ما شرحنا في قصص الأنبياء، \nوكمان الكلام إللي سمعه من بُحيرى الراهب والناس إللي كان بيشوفهم بيدعوا لدين إبراهيم زي\n《 قِس بن ساعدة و زيد بن عمرو بن نُفيل》\nفكان عارف إن في إله ليس كمثله شيء، وإن له طريقة معينة في العبادة، \nفكان بيخرج للجبال ويقعد أيام برة البيت يتدبر ويتفكر الإله  خالق الكون ده ويتفكر في أحداث حياته إللي عدت وكأنه كان مستني حاجة\nوعبادة التفكر دي عبادة عظيمة هشرحها لكم بعد ما احكي لكم قصة زيد بن عمرو بن نفيل ،\nلأن قصته عجيبة فعلا\nاحنا عارفين إن الناس في الجاهلية كانوا بيعبدوا الأصنام وكان في بقايا من أهل الكتاب من اليهود والنصارى،\nففي يوم من الأيام لما كان أهل مكة اجتمعوا مرة يذبحوا ذبيحة عند صنم لهم،\nانعزل عنهم كم رجل كده، منهم زيد بن عمرو بن نُفيل، وورقة بن نوفل.. قالوا لبعض:\nوالله الناس دي بتعبد حجر لا يضر ولا ينفع...الله يخلق البهائم وينزل لها المطر من السماء ويُخرج لها العشب من الأرض تأكله والناس يذبحوها لغيره\nفقالوا لبعض: طب والحل\nقالوا : خلونا ندوّر على الدين الصحيح \nفكل واحد راح في طريق يبحث عن الدين الحق، ورقة بن نوفل قابل راهب من رهبان النصارى ،\nفتعلم منه النصرانية فتنصر وبقى على دين عيسى عليه السلام وبقى عالم في النصرانية،\nزيد بن عمرو بن نفيل قابل واحد من علماء اليهود فسأله عن الدين الحق فقعد يشرح له الدين فزي ما تقولوا مقتنعش\nإنتم عارفين تحريفات اليهود في التوراة\nفسأله عن دين تاني فالعالم اليهودي قال له:\nالدين الوحيد إللي أعرفه غير اليهودية هو إنك تكون حَنِيف،\nفقال له: يعني إيه حنيف\n...فاليهودي قال له:\n إنك تكون على دين إبراهيم\nطيب إيه هو دين إبراهيم\nقال له : معرفش ..ده دين قديييم اندثر محدش يعرف عنه حاجة\nفمشي وسابه واستمر يبحث عن الدين، لحد ما قابل واحد من علماء النصارى سأله عن الدين،\nفحصل معاه زي برده ما حصل مع اليهودي، لأن برده النصرانية كان دخل فيها تحريف،\nاحنا بنتكلم في أكثر من خمسمائة سنة بعد رفع عيسى عليه السلام \nوالإنجيل محدش بدأ يكتبه إلا بعد مئتين سنة من رفع عيسى عليه السلام، فحصل تحريف في الإنجيل.\n☆الإنسان إللي فطرته سليمة لما بيسمع حاجة في الدين غلط قلبه بيحس إن في حاجة غلط...مش مرتاح..مش متطمن\nومن هنا جاء حديث : \n\" استفت نفسك وإن أفتاك الناس وأفتوك\"\nوحديث:\n\" اسْتَفْتِ قَلْبَكَ وَاسْتَفْتِ نَفْسَكَ ثَلَاثَ مَرَّاتٍ، الْبِرُّ مَا اطْمَأَنَّتْ إِلَيْهِ النَّفْسُ ،\nوَالْإِثْمُ مَا حَاكَ فِي النَّفْسِ وَتَرَدَّدَ فِي الصَّدْرِ وَإِنْ أَفْتَاكَ النَّاسُ وَأَفْتَوْكَ\"\nيعني ممكن مثلا حد يفتيك بحاجة إنها حلال و بعدين حسيت من قلبك كده إن إللي بيفتي ده بيألف وانت من جواك مش متطمن وقلقان...فهنا بقى لا يجوز العمل بالفتوى لو إنت مش متطمن لها تخيلوا\nمثلا يعني الشيخ إللي يقول النمص حلال مطلقا أو النمص حلال لو بإذن الزوج...المرأة هتحس من جواها هتحسي بإنها مش مطمئنة كده\nوهتلاقوا فتاوى كتير كده فعلا تسمعوها تحس إن القلب مش مرتاح لها \nأهه لو حسيت بكده مينفعش نقول أنا مليش دعوة أنا هاخد برأي الشيخ وخلاص وحطها في رقبة عالم واطلع سالم\nلا يا جماعة مينفعش..مفيش الكلام ده \nالفتوى من المُفتي مش هتخلصك من ربنا لو إنت شكيت ولو للحظة من جواك إن الفتوى فيها حاجة مريبة وإنت مش مرتاح للموضوع\nبس استنووووا\nالكلام ده \n للمؤمن صاحب القلب السليم\nيعني ميجيش واحد غرقان في المعاصي والموبقات ونقول له حلال وحرام يقول لك:  هستفتي قلبي\nأهه ده لو استَفْتى قلبه في الكبائر مثلا...قلبه هيقول له:\n حلالٌ حلالٌ حلال \nفلما تسمع كلام حد من بتوع الفتاوى إياها وحسيت إن قلبك مش مستريح للكلام..افرح...لأن قلبك كده يبقى سليم\nواحنا عندنا القاعدة بتقول إييييه:\n\"يوم لا ينفع مال ولا بنون إلا من أتى الله \n《بقلب سليم》\" \n《الكلام بالتفصيل في شرح الحديث على موقع الإسلام سؤال وجواب》\nفزيد بن عمرو بن نفيل كانت فطرته سليمة وكان فعلا صادق في بحثه عن الحق ،\nعشان كده حس إن كلام النصراني مش مقنع بالنسبة له فسأله زيد : مفيش دين تاني،\nفقال له النصراني : معرفش غير إنك تكون حنيف\nفقال له : يعني إيه حنيف\nقال له : دين إبراهيم وقال له زي ما قال اليهودي،\nفقال زيد بن عمرو بن نفيل:\nيارب أشهدك إني على دين إبراهيم ..كلهم بيقولوا إن هو ده الدين الصحيح ،\nفأنا على الدين الصحيح لكن أنا معرفش إيه طريقة العبادة بتاعته وإيه هي الشرائع بتاعته\nفسبحان الله ربنا هداه إنه يعمل حاجات من دين التوحيد،\nزي إنه مياكلش إلا من الذبائح إللي ذُكر اسم الله عليها،\nوكان بيقعد ينصح الناس في مكة ويدعوهم للتوحيد،\nوكان لو شاف واحد عايز يُوْئد بنته، يدفنها حية يعني كان يمنعه ويقول له أنا أكفلها لك وهصرف عليها لحد ما تكبر،\nوكان أهل مكة بيؤذوه ويمنعوه إنه يدعو للدين بتاعه ده وكانوا بيطردوه برة مكة\nوفي يوم من الأيام وهو قاعد عند الكعبة عدّى عليه واحد اسمه: 《أُمية بن أبي الصّلت》\nوكان أمية ده على التوحيد وكان على طول بيقول شعر بيوصف الجنة والنار ومكنش بيعبد الأصنام وكان على علاقة بأهل الكتاب،\nوكان مستني نبي آخر الزمان، فقال أمية لزيد :\nهااا لقيت الدين إللي كنت بتدور عليه\nقال له زيد: أنا على الحنيفية دين إبراهيم بس معرفش حاجة عنه،\nفقال له أمية: في نبي هيخرج واحنا مستنيينه عشان نتبعه\nمين إللي كان سامع الحوار ده بين زيد وأمية\nشاب في بداية الثلاثينات من عمره اسمه:\n《عبد الله بن عثمان أو عبد الله بن أبي قحافة》 \nخلينا نقول الإسم إللي اتشهر بيه بعد كده\n كان اسم الشاب:《أبو بكر الصديق》\nاحفظوا الاسم ده كويس عشان له دور كبير جدا بعدين \n☆الحوار ده كان بعد قصة إعادة بناء الكعبة على طول يعني لما كان محمد بن عبد الله عمره خمسة وثلاثين عام.\n في يوم من الأيام خرج زيد بن عمرو في سفر فقابل واحد من علماء النصارى فقال له:\n الزمن إللي احنا فيه دلوقتي ده زمن خروج آخر الانبياء زي ما مكتوب في الإنجيل،\nفرجع زيد بن عمرو لمكة عشان يستنى النبي إللي هيخرج وهو في الطريق طلع عليه ناس هجموا عليه عشان يقتلوه فقبل ما يموت قال : \nيارب أنا ملحقتش أصاحب نبيك فمتحرمش ابني سعيد من صحبته\nوفعلا ربنا استجاب دعاؤه وسعيد بن زيد بن عمرو بن نفيل آمن برسول الله ﷺ وكمان بقى من العشرة المبشرين بالجنة\n☆شوفتوا إزاي قاعدة وكان أبوهما صالحا بتحصل في كل زمن زي ما قلنا في قصة الخضر مع الغلامين إللي اتكلمنا عنه في قصص الأنبياء\nوزيد نفسه من أهل الجنة مات على التوحيد...إللي عايز الهداية من قلبه وأخذ بالأسباب عشان يهتدي ربنا سيهديه أكيد\nغير إللي قاعد وعمال يقول يارب اهديني وهو مش بيسعي في طريق الهداية\nشوفوا ربنا بيقول إيه :\n\"وَمَنْ أَرَادَ الْآخِرَةَ وَسَعَىٰ لَهَا سَعْيَهَا وَهُوَ مُؤْمِنٌ فَأُولَٰئِكَ كَانَ سَعْيُهُمْ مَشْكُورًا\"\nأهِي الآية دي بتلخّص قصة زيد بن عمرو بن نفيل،\nهو أراد رضا الله والدار الآخر فآمن بالله،\nوخرج يتعلم الدين الصحيح وعمل كل إللي يقدر عليه عشان  يوصل لعبادة ربنا صح،\nثبت لوحده على الإيمان وسط مجتمع كله كفر وأمر بالمعروف ونهى المنكر ومقلش مليش دعوة\nعشان كده ربنا تقبله وأدخله الجنة\nيا ترى حالكم إنتم إيه ؟\nخليكم دايما فاكرين :\n\"وَمَنْ أَرَادَ الْآخِرَةَ وَسَعَىٰ لَهَا سَعْيَهَا وَهُوَ مُؤْمِنٌ فَأُولَٰئِكَ كَانَ سَعْيُهُمْ مَشْكُورًا\"\nفكان محمد بن عبد الله في سن الأربعين بيخرج ويعتكف في غار في جبل اسمه غار حراء عشان يتعبد ويتفكر في الإله خالق الكون،\nوكان بيتزود من الأكل والماء ويأخذه معاه\n☆في هنا نقطة مهمة هوضحها عشان لو كان حد قرأها،\nكان في حد قال وهو بيشرح السيرة:\n《 إن السيدة خديجة كانت كل أربعة أيام بتروح تعطي رسول الله الأكل والماء، ورسول الله قاعد في الغار يتعبد،\nوكانت عجوز وكان عمرها خمسة وخمسين سنة، \nوكان رسول الله بيكرر الموضوع ده كذا مرة في السنة  \nوكانت بتطلع الجبل ومع ذلك ماشتكتش وكانت بتقعد جنبه ومش بتتكلم وتنزل من الجبل وتروح تاخد بالها من عيالها》\nالكلام ده \nغير صحيح إطلااااقا \nيعني غير إنه مش من المروءة أصلا ولا الرجولة إن رسول الله ﷺ يبقى قاعد ويسيب امرأة عجوز تطلع وتنزل جبل ولا حتى من أخلاقه نهائي،\nوكمان تمشي في طريق وَعِر غير ممهد لوحدها،\nوكمان امرأة عزيزة غنية جدا زي خديجة عندها عبيد هتخلي العبيد يقعدوا وهي إللي هتخرج توصل الأكل والماء لرسول الله ﷺ وتسيب أبنائها لوحدهم في البيت\nده كان لما زوجة من زوجاته تأتيه وهو معتكف في مسجد المدينة وبيوت نسائه كانت قريبة جدا من المسجد كان يسيب الاعتكاف ويخرج يوصلها زي ما هنشوف بعدين\nكمان في الحديث الصحيح الصريح في البخاري هو نفسه قال إنه كان بيتزوّد من الطعام والماء لما يكون ناوي يخرج،\nولما الزاد بتاعه يخلص كان هو إللي بيرجع لخديجة ياخد زاد تاني وبعدين يرجع يتعبد\nوكان بيخرج 《شهر واحد فقط》 في السنة بيتعبد ويختلي فيه وهو شهر رمضان،\nوباقي الشهور بيمارس حياته الطبيعية ويمارس حياته كزوج وأب..يعني مكنش منقطع للعبادة ومضيع مسؤولياته\n◇وعبادة التفكر إللي كان بيتعبدها رسول الله هي عبادة قلبية،\nبتزيد الإيمان وبتخلينا نشوف عظمة الخالق وتدبيره للكون\nهحكي لكم موقف حصل مع أحد أعرفه،\nالموقف يُعتبر بسيط جدا لكن لو فكرنا فيه بتدبر هنشوف إزاي ربنا بيدبر الرّزق لخلقه\nرجل اتفق مع زوجته إنهم هيتغدوا اليوم ده غذاء معين، فنزل راح مشوار،\nبقدر ربنا يروح السوق يلاقي رجل بيبيع سمك فبعد ما اشترى منه وخلاص هيمشي شاف سمكة لوحدها فسأله على نوع السمكة دي لأنها جديدة بالنسبة له،\n فقال له البائع : أنا كنت هشويها لنفسي خلاص خذها لأن حصلت ظروف ومش هعرف اشويها،\nالزوج أخذ السمك ورجع البيت بيفتحوا السمكة إللي الراجل أعطاها له عشان ينظفوها لقوا فيها سمك صغير كثير السمكة دي كانت لسه واكلاه،\nالمهم قالوا: السمك ده كثير خلينا نجمعه في كيس ونروح نحطه للقطط.\nركزوا كده معايا السمكة إللي في البحر أكلت السمك الصغير  والصياد خرج عشان يصطاد فاصطاد السمكة دي بالذات وتحصل له ظروف وميعرفش هو ياكلها،\nعشان الرجل يأخذها ويروح البيت ويطلع السمك الصغير ده \nويحطه للقطة إللي بتمشي على الأرض عشان تأكله،\nيعني رزق القطة إللي طبيعتها مبتحبش المية كان سمك من أعماق البحر \nإيه رأيكم في عبادة التدبر والتفكر \nوهتلاقوا أمثلة كثير في القرآن وفي انفسنا وفي حياتنا وحياة إللي حوالينا،\nعبادة التدبر والتفكر من أعظم العبادات القلبية إللي بتزود الإيمان وتُعلّق القلب بالله،\nوكثير من الناس مش بياخد باله منها وبيركز على عبادات الجوارح زي الصلاة والصيام وقراءة القرآن،\nفابدأوا في عبادة التفكر والتدبر زي ما كان محمد بن عبد الله بيعمل في غار حراء\nفي السنة إللي تم فيها عمره أربعين سنة ، خرج محمد بن عبد الله عشان يتعبد زي كل سنة في غار حراء،\nوالغار عبارة عن فتحة في جبل والغار عشان حد يوصله لازم يتسلق الجبل،\nفلو حد جاء يتسلق هيعمل صوت والشخص إللي في الغار هيعرف إن في حد برة بيتسلق الجبل،\nفالمكان إللي هو فيه كان مكان منعزل تماما عن الناس عشان يقدر يركز في العبادة ،\nمفيش في المكان ده أي انسان مفيش أي صوت نهائي هدووووء تااام وهو قاعد لوحده جوه الغار بيتعبد زي ما بيعمل كل سنة...فجأة لقى انسان في وشه جوه الغار\nمتخيلين قمة الرعب إللي هو كان فيها\nاحنا لو في البيت وسط أهلنا ودخلنا الأوضة وبعدين فجأة لقيت حد وراك من إخواتك مخدتش بالك إنه دخل وراك  بيبقى قلبك هيقف من الخضة\nده بقى كان لوحده خااالص وفجأة بدون مقدمات لقى قصاده الإنسان ده ...وياريته مثلا بدأ يِهَدي فيه ويقول له متخافش وبدأ يعرفه على نفسه،\nلأ ...ده دخل عليه وقال له : اقرأ\nكده خبط لزق \nفمحمد بن عبد الله بكل أدب وأخلاق عالية قال له: أنا مبعرفش أقرأ!!\nمع إنه من حقه إنه ميردش على كلامه ويقول له: \nإنت مين أصلا وجيت هنا إزاي وأسئلة كثيرة، ومع ذلك رد على السؤال \nراح الرجل حضنه حضن شديد جدا لدرجة إنه حس إن روحه هتطلع من شدة ضغط الحضن\nفالرجل تركه، فمحمد بن عبد الله لسه بياخد نفسه راح الرجل قال له تاني: اقرأ\nفقال له : أنا مبعرفش أقرأ!!!\nفحضنه مرة ثانية لحد ما حس إنه روحه هتطلع وبعدين تركه وقال له تاني: اقرأ\nفقال له : مبعرفش أقرأ!!!!\nفراح حضنه مرة ثالثة لحد ما حس إنه روحه هتطلع برده\nوبعدين تركه وقال له الرجل:\n\"اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ\nخَلَقَ الإِنسَانَ مِنْ عَلَقٍ\nاقْرَأْ وَرَبُّكَ الأَكْرَمُ\nالَّذِي عَلَّمَ بِالْقَلَمِ\nعَلَّمَ الإِنسَانَ مَا لَمْ يَعْلَمْ\"\nالرجل قال الكلام ده واختفى من قصاده\nطبعا محمد بن عبد الله في قمة الذهول \nإيه ده؟!!\nقمة الرعب مع قمة الألم والعنف وإيه الكلام العجيب ده إللي أول مرة أسمعه؟!!\nأنا أفصح وأبلغ العرب ..الكلام ده مش كلام بشر ... مفيش كلام زي الكلام ده!!!\nثم الرجل ده بيتكلم عن الإله إللي أنا بؤمن به من سنين لكن معرفش عنه حاجة،\nتساؤلات كثيييرة وخوف شديد جدا خلاه ينزل من الغار ويطلع يجري بسرعة ،\nلحد ما وصل لبيته ودخل على زوجته خديجة وجسمه بيرتعش من شدة الخوف وقلبه هيقف من الرعب وقعد يقول غطوني غطوني!!!\nفخديجة لما شافته اتفاجئت أول مرة تشوف زوجها الطيب الشجاع الصادق صاحب الأخلاق العالية في الصورة دي\nفعرفت إنها في موقف زي كده مينفعش هي كمان تخاف  وإن زوجها محتاج حد يطمنه\nفبدأت تهدّيه وتسأله إيه إللي حصل،\nفحكى لها إللي حصل معاه وقال لها والله أنا خفت على نفسي !!!\nفقالت له بكل هدوووء : \nمتخفش ربنا مش هيضيعك أبدا عارف ليه ؟\nلأنك كنت بتُحسن لأقاربك بالمال أو الخدمة وغيرها،\nوإنت صادق في كلامك عمرك ما كنت بتكذب، وكنت بتساعد الضعيف واليتيم وصاحب العيال الفقير،\nوكمان كنت بتكرم ضيوفك وأي حاجة فيها خير مكنتش بتتأخر عنها\nفهدأ زوجها واطمأن لكلامها كأنه تذكر إن صنائع المعروف تقي مصارع السوء \nمين الرجل إللي جاء لمحمد بن عبد الله؟\nوليه عامله بالعنف الشديد ده؟\nوإيه الكلام إللي قاله له ومشي؟\nوهل رجع له تاني ولّا لأ؟\nده إللي هنعرفه الجزء الجاي إن شاء الله\nباقي  القصص  هنا"}, {"n": 45, "l": "الجزء التاسع | المدثر | والجزء العاشر | بداية الدعوه", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_التاسعة\n#المدثر\nوقفنا المرة إللي فاتت عند محمد بن عبد الله لما نزل من الغار وهو خايف وراح لزوجته خديجة وهو مرعوب من إللي شافه فزوجته قعدت تهدّيه وتقول له متخفش ربنا مش هيضيعك،\nوقعدت تذكره بصفاته وأخلاقه وأعماله الصالحة فهدِي واطمأن\nلكن برده مسابوش نفسهم للأوهام وياترى الرجل ده كان جن ولّا كان إيه بالضبط\nبدأوا يدوّروا مين إللي يقدر يفسر لهم إللي حصل ده،\nفخديجة كان لها ابن عم اسمه ورقة بن نوفل فاكرينه\nهي كانت عارفة عن ورقة بن نوفل إنه تنصّر وكان عنده علم كثير،\nفشافت إن ده أنسب واحد يقدر يفسر لهم إللي حصل\n☆وهنا خديجة رضي الله عنها بتعلمنا حاجة مهمة جدا وهي إننا نسأل الناس إللي عندها علم فعلا،\nهي ليه مقالتش خلينا نروح نسأل الكهنة، ولّا سادات قريش\nلأنها عارفة إنهم مهما كان عندهم علم بسبب اتصالهم بالجن فمش همّ دول إللي هيدّوها الإجابة المضبوطة\nوخصوصا إنها عارفة إن زوجها محمد لا يحب الكهنة ولا السحرة ولا الأصنام\nفأخذت زوجها وراحوا لورقة بن بن نوفل وكان ورقة في الوقت ده شيخ كبير وأصابه العمى،\nفخديجة قالت لورقة:\nفي حاجة غريبة حصلت فاسمع من ابن أخيك\nفحكى محمد بن عبد الله لورقة كل إللي حصل معاه وإزاي إن الرجل حضنه جدا لدرجة إن كان حاسس إن روحه هتطلع\n☆سؤال هنا\nهو ليه جبريل عليه السلام حضن رسول الله ﷺ بشدة كده وخلّاه يتألم\nشوفوا،\nجبريل عليه السلام من الملائكة وهو أعظم الملائكة وأشرفهم مكانة عند الله،\nوالملائكة دول مخلوقات بتعمل إللي ربنا يقول لها عليه،\nيعني محدش فيهم بيتصرف كده منه لنفسه\nفجبريل عليه السلام لما عمل كده مع رسول الله ﷺ كان بأمر من ربنا عشان يوضح نقطتين مهمين:\n◇أولا: \nدي رسالة لنا إن يا أيها الناس محمد بن عبد الله ده بشر زيكم بيخاف زيكم وبيمرض وبياكل وبيشرب،\nوبيحس بالألم فكل حاجة هيعملها بعد كده يستطيع أي بشر إنه يقلّده فيها،\nيعني هو معندهوش قوة خارقة ولا حاجة...هو بشر\n◇ثانيا: \nالعنف ده كله عشان جبريل يقول لرسول الله ﷺ بلسان الحال:\n يا محمد انتبه إنت مش بتحلم..إنت مش بيتهيأ لك...ولا دي أحلام يقظة..\nإللي بيحصل لك كده حقيقي ..انتبه كويس عشان الكلام إللي هقوله\nفبدل ما جبريل عليه السلام يقعد يشرح الكلام ده بلسانه وصل له المعنى بإنه يحضنه بقوة ثلاث مرات\nوخصوصا إنه قال له اقرأ وجبريل عارف إن رسول الله ﷺ لا يعرف القراءة والكتابة،\nزي ما المدرس بيقول للطلبة بتوعه اكتبوا فالكل بيستعد للكتابة،\nفقال له اقرأ عشان يستعد لقراءة الكلام إللي هيقوله\nورقة بن نوفل عمال يسمع ويسمع وفجأة قال:\nالله أكبر...إنت جاءك الناموس الأكبر إللي كان بينزل على موسى\nياريتني كنت صغير في السن...شاب قوي وأنا كنت هنصرك بقوة لما قومك يخرجوك من بلدك\n☆ورقة بن نوفل كان عارف إن الزمن ده زمن نبي وكان مستنيه عشان يؤمن به ، لأن وصف الزمن ووصف النبي ده كان موجود عند أهل الكتاب من اليهود والنصارى\nمحمد بن عبد الله بيسمع كلام ورقة بن نوفل...\nناموس أكبر إيه ...ومين دول إللي هيخرجوني من مكة؟\nقومي ..أهل مكة يخرجوني أنا؟\nالصادق الأمين؟\nده همّ إللي أطلقوا علي اللقب ده،\nيخرجوني أنا؟\nأنا إللي بساعد المظلومين والفقراء والأيتام وبكرِم الضيوف؟\nيخرجوني أنا وأنا أشرف الناس نسبا ومن سادات مكة وحفيد عبد المطلب إللي الناس كانت بتهابه وبتعمل له ألف حساب؟ \nفقال له ورقة بن نوفل:\nالناموس الأكبر هو جبريل إللي بينزل على الأنبياء..يعني إنت دلوقتي نبي\nومفيش أي أحد جاء باللي إنت جئت به ده إلا عُودِي،\nيعني الناس بقوا أعداء له وآذوه\n☆أنا عايزاكم تتخيلوا المشاعر إللي كانت في قلب محمد بن عبد الله في اللحظة دي\nتخيل نفسك كده وإنت لسه بادئ إلتزام أو واحدة مثلا عايزة تلبس النقاب،\nوييجي حد يبدأ يقولك خد بالك الناس مش هتسيبك،\nحتى أهلك هتلاقيهم بيعارضوك في كل حاجة وهيقعدوا يتريقوا ويقولوا أيوة يا سيدنا الشيخ وكلام كثيييير،\nفإنت تستغرب...ليه..هو أنا هعمل حاجة غلط\nده أنا هطيع ربنا وأحفظ نفسي من الفتن عشان أدخل الجنة\nأهه ده نفس الموقف إللي كان فيه محمد بن عبد الله\nطبعا هو دلوقتي مستغرب ومش فاهم يعني إيه أنبياء ولا إيه قصة حياتهم،\nهو ممكن كان بيكون سمع كلمة من هنا على كلمة من هنا لكن ميعرفش أي حاجة عنهم نهائي\n◇عارفين قصص الأنبياء إللي اتكلمنا عنهم، في الوقت ده مكنش يعرف عنهم أي حاجة خالص حتى ربنا قال له في القرآن:\n\"تِلْكَ مِنْ أَنْبَاءِ الْغَيْبِ نُوحِيهَا إِلَيْكَ مَا كُنْتَ تَعْلَمُهَا أَنْتَ وَلا قَوْمُكَ مِنْ قَبْلِ هَذَا \"\nفبدأ يتساءل: نبي...أنا...طب إزاي؟ \nمعقول ربنا اختارني أنا من بين كل البشر عشان أكون نبي آخر الزمان؟\n☆أصل النبوة دي يا جماعة بتبقى اختيار من عند ربنا\nمش واحد مثلا يقعد يعبد ربنا ويجتهد في العبادة فربنا يعطي له النبوة\nالنبوة دي اختيار من عند ربنا فقط\n\"اللَّهُ يَصْطَفِي مِنَ الْمَلَائِكَةِ رُسُلًا وَمِنَ النَّاسِ ۚ \"\nربنا المُطّلع على قلوب العباد اختار محمد بن عبد الله عشان يكون هو آخر الأنبياء والمرسلين\nواختار أطهر الناس قلوبا عشان هيكونوا معاه ويساعدوه في تبليغ الرسالة بتاعته\nفلو أحد فينا كان يستحق إنه يكون في زمن الناس دي كان ربنا حطه فيه؛\nلأن قلوبنا مهما بلغت من الطهارة والنقاء فعمرها ما هتكون زي قلوب الصحابة فهم أول من يدخل الجنة بعد الأنبياء\nوإنتم هتشوفوا بنفسكم الصحابة دول عملوا إيه،\nوساعتها احكموا هل فعلا الناس دي كانت تستحق إنها تصاحب رسول الله ﷺ ويكون لها المكانة دي ولّا لأ \n¤ ملحوظة مهمة \nحديث رسول الله ﷺ:\n\"إن من ورائكم أيام الصبر ، للمتمسك فيهن يومئذ بما أنتم عليه أجر خمسين منكم  قال :\n يا نبي الله ! أو منهم ؟ قال : 《بل منكم 》\nده مش معناه إن في حد هيكون أفضل من الصحابة،\nلأن الصحابة لهم أجرين: أجر العمل وأجر صحبة رسول الله ﷺ.\nوكمان رسول الله قال 《للمتمسّك》\nيعني واحد متمسك بدينه مش بياخد من الدين إللي على هواه، \nلأ، ده بيعمل زي الصحابة فيأخذ زي أجر خمسين من الصحابة بسبب إن《 المتسمك》 بدينه ده مش هيلاقي أحد يعينه وهيتحارب من كل الجهات لكنه هيفضل متمسك بدينه \nفعشان كده ربنا هيعطي له أجر خمسين واحد من الصحابة ومش معنى إن الأجر أكثر منهم يبقى إللي أجره أعلى يكون أفضل،\nوخصوصا إن رسول الله ﷺ قال :\n\"لو أن أحدكم أنفق مثل أحدٍ ذهباً ما أدرك مُدّ أحدهم ولا نصيفه\"\nيعني لو أنفق واحد فينا زي جبل أحد ذهب مش هياخد نص أجر واحد منهم تصدق بطعامه، فخذوها قاعدة:\n أفضل الناس هم الصحابة \nوهنعرف من خلال السيرة من هُم الصحابة إن شاء الله\nخرج محمد بن عبد الله من عند ورقة بن نوفل وهو محتار.. مشاعره متلخبطة...\nورقة بن نوفل قال له إنه نبي والرجل إللي جاله في الغار مجبش سيرة عن موضوع النبوة ده\nوهو دلوقتي مش عارف يعمل إيه ولا إيه المطلوب منه أساسا\nوعنده أسئلة كثيرة محتاج حد يجاوب له عليها، \nبجد قمة الحيرة \nنحط نفسنا مكانه كده لما دماغنا يبقى فيها أسئلة كثيرة ومش لاقيين لها إجابة ومحتاجين حد يفهمنا بنكون محتارين إزاي؟\nأهه هو حيرته كانت أشد لأن الوحيد إللي يقدر يجاوب على الأسئلة دي هو الرجل إللي قابله في الغار\nبس هو خايف منه...ده كان هيموته...طب برده أنا عايز أقابله،\nفكان محمد بن عبد الله في حيرة شديدة،\nعدى يوم واثنين وثلاثة والخوف بدأ يقل،\nوالشوق لرؤية الرجل ده مرة ثانية بدأ يزيد لحد ما تمنى إنه يقابله تاني\nلدرجة إنه بقى يخرج في الصحراء والجبال لعل الرجل ده ييجي تاني\nهو عايز يفصِل الموضوع هل أنا نبي فعلا ولّا إيه؟\nلكن الرجل مظهرش...استنى يوم ويومين وأسبوع وأسبوعين ومفيش حد...لدرجة إنه بقى حزين إن الرجل مجاش،\nفبعد ما كان خايف من الرجل بقى هو إللي بيدور عليه\nوده كان الهدف من فترة انقطاع الوحي\nلأن حامل الرسالة لو مكنش متشوق وعايز الرسالة دي مش هيقدر عليها وهيستسلم على طول\n☆زي الإلتزام كده وطلب العلم\n لو احنا من جوانا مش عايزين نلتزم بأوامر الله ومش ومتشوقين إننا نتعلم ديننا وشايفين إن الموضوع حِمل علينا مش هنقدر نكمل\n◇العلماء على خلاف في المدة إللي انتظرها رسول الله ﷺ قبل ما ينزل عليه جبريل عليه السلام مرة ثانية،\nفمدة فتور الوحي كانت ما بين ثلاثة أيام لأربعين يوم، \nوده أرجح الأقوال لأن في ناس تانية قالت انقطع سنتين أو ثلاث سنين ،وده مش منطقي خالص حتى\n◇وفي هنا برده نقطة مهمة \nوهي الحديث إللي بيقول إن رسول الله ﷺ كان بيحاول يرمي نفسه من على جبل عشان ينتحر بسبب حزنه الشديد لانقطاع الوحي، فجبريل كان بييجي له فيمنعه ويقول له إنت رسول الله حقا ،فيهدأ ويتراجع عن الإنتحار.\nالكلام ده غير صحيح بالمرة\nلأن ده مش حديث ده كان تعليق من واحد من التابعين اسمه الزّهْري على حديث لعائشة رضي الله عنها ،يعني مش حديث حديث عن رسول الله ﷺ ولا عن الصحابة\n《المسألة فيها شرح كثير موجود في موقع الإسلام سؤال وجواب لمن أراد التفصيل》\nخلال فترة انقطاع الوحي دي مات ورقة بن نوفل\nمات قبل ما يعرف إيه هي رسالة محمد بن عبد الله،\nعاش باحث عن الحق مستني نبي آخر الزمان،\nفربنا أكرمه إنه يقابل نبي آخر الزمان مات وهو ناوي إنه يتبع النبي ده،\nعشان كده كان جزاءه عند ربنا إنه يكون من أهل الجنة، ويلحق بصاحبه زيد بن عمرو بن نفيل\nفي يوم من الأيام خرج محمد بن عبد الله لعله يقابل الرجل،\nفا وهو ماشي فجأة سمع حد بينده عليه، بص وراه وكانت المفاجأة\nمنظر أول مرة يشوفه في حياته ...لدرجة إنه وقع على ركبته من شدة الرعب والذهول والتعجب وكل المشاعر إللي ممكن الإنسان يتخيلها \nمخلوق ضخم من نور له ستمائة جناح قاعد على كرسي والكرسي متعلق في الهواء بين السماء والأرض\n\"وَلَقَدْ رَآهُ بِالْأُفُقِ الْمُبِينِ\"\nومن شدة الخوف والرعب قام يجري ورجع لبيته وهو بيقول لهم:\nزمّلُوني ...دثروني...يعني غطوني.\nفسمع صوت بيكلمه:\nيا أيها المدثر ..قم فأنذر وخوف الناس وحذرهم من عذاب ربك لو لم يؤمنوا\nوربك فكبر ..عظّم ربك عما يقوله عبدة الاصنام،\nوثيابك فطهرها من النجاسات إللي المشركين مكنوش بيتطهروا منها،\nواجعل قلبك وعملك طاهرين\nوالرُّجْز فاهجر..يعني اترك كل حاجة من الأقوال والأفعال ممكن تكون سبب في العذاب \nولا تَمْنن تستكثر..يعني لا تعطي الناس العطاء وتستنى إنك تأخذ مقابل أكثر منه،\nولا تقعد تَمُن على ربك باللي هتتحمله من أعباء الدعوة،\nتقول أنا بعمل كذا وكذا وبستحمل كذا...\nومتشوفش عملك إنه عظيم فتقول خلاص كفاية كده مش هزوّد من عمل الخير\nومتعملش طاعة لله وتطلب قصادها مقابل،\nلكن اصبر لحد ما ربنا هو إللي يعطيك الثواب من عنده\n☆يعني زينا كده لما نقعد نقول أنا بسمع كلام ربنا أهه وبعمل الطاعات ..ليه ربنا بقى بيبتليني.. فين جزائي على الطاعة..فين من يتقي الله يجعل له مخرجا...فين...فين...\nنعمل ومنطلبش، نصبر لحد ما ربنا هو إللي يعطينا الأجر\nولربك فاصبر..يعني اصبر على الأذى في سبيل الله والدعوة وخلي صبرك على الأذى إللي هتشوفه ده لله\nدلوقتي محمد بن عبد الله مبقاش إنسان عادي..بقى اسمه محمد رسول الله \nحياته اتغيرت من اللحظة دي...بقى عنده رسالة..عنده هدف،\nمهمته صعبة جدا..ويمكن تكون مستحيلة من وجهة نظرنا احنا كبشر\nعارفين ليه؟\nلأن مطلوب من إنسان عايش في قرية ناااائية لا تكاد تُذكر أصلا بين أهل الأرض في الزمن بتاعه، إنه يبلّغ أهل الأرض كلهم إن هو رسول من عند خالق الكون،\nوإنهم لازم يتبعوه\nأقرب لكم الصورة...تخيلوا واحد من قرى العالم إللي منسمعش عنها فجأة كده طلع وطلب من رئيس أمريكا وروسيا وكل بلاد وشعوب الأرض إنهم يتبعوه ويسمعوا كلامه..رد الفعل هيكون عامل إزاي\nحد هيسمع كلامه... حد هيهتم بيه أساسا\nأهه بالضبط كده ده كان مع محمد رسول الله ﷺ\nلوحده في وسط الكرة الأرضية..مش معاه حد نهائي ..إزاي هيدعو الناس ويوصل رسالته\nإن شاء الله الجزء الجاي هنعرف إيه الخطوات إللي بدأها \nمحمد رسول الله ﷺ عشان يقدر يوصّل رسالته \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_العاشرة\n#بداية_الدعوة\nوقفنا المرة إللي فاتت عند جبريل عليه السلام لما أنزل أول آيات القرآن على رسول الله ﷺ بعد فترة انقطاع الوحي وكانت الآيات هي:\n\"يَا أَيُّهَا الْمُدَّثِّرُ. قُمْ فَأَنذِرْ. وَرَبَّكَ فَكَبِّرْ.\n وَثِيَابَكَ فَطَهِّرْ. وَالرُّجْزَ فَاهْجُرْ. وَلا تَمْنُن تَسْتَكْثِرُ. وَلِرَبِّكَ فَاصْبِر\"\nوالأيات هنا فِعل أمر\nوالأمر لما بييجي من الأعلى للأدني يعني حد أعلى منزلة لأحد أقل منزلة يبقى لازم تنفيذه فورا،\nفالأمر جاء لرسول الله ﷺ من رب العالمين يبقى لازم ينفذه\nالمشكلة بقى إنه هينفذ الأمر ده إزاي أصلا وهو مطلوب منه إنه يوصل الإنذار والرسالة دي لكل أهل الأرض\nوأهل الأرض مش بس البشر ..لأ ده كمان رسول للجن\nيعني هو رسالته لكل أهل الأرض من البشر وكمان من الجن،\nفرسول الله ﷺ هو أول رسول للإنس والجن مع بعض،\nكل رسول كان بيكون لقومه خاصة والجن ربنا كان بيبعث لهم رسل زيهم من جنسهم زي ما قال العلماء،\nلكن محمد رسول الله ﷺ هو أول نبي ورسول لأهل الأرض جميعا من الجن والإنس إللي همّ الثقلين \nخلينا نركز مع بعض كده ونشوف أهل الأرض في الزمن بتاعه كانوا عاملين إزاي ،\nعشان نشوف هل في تشابه بين زمن رسول الله ﷺ إللي بدأ فيه الدعوة وهو كان لوحده بمعنى كلمة لوحده،\nوبين زماننا دلوقتي إللي احنا عايشين فيه وهل نقدر نعمل زيه ولّا لأ؟\nخلونا نأخذهم واحدة واحدة ،نبتدي من البلد إللي رسول الله ﷺ كان عايش فيها،\n وكل واحد فينا يبدأ يربط بين المكان إللي هو عايش فيه وبين وضع رسول الله ﷺ \nرسول الله ﷺ كان عايش في بلد كل أهلها بيعبدوا الأصنام وبيقولوا إن دي هي الألهة بتاعتهم،\nطبعا مكنوش بيؤمنوا بحاجة اسمها إن في يوم قيامة ولا جنة ولا نار ولا إنهم هيبعثوا بعد الموت مرة أخرى\nهي بس حياتهم الدنيا دي بيعيشوها بكل ملذاتها،\nويعملوا إللي هم عايزينه ويموتوا وخلاص انتهى الموضوع على كده،\nومش بس كده...ده المجتمع مع الشرك والكفر إللي هو كان فيه ده كان مجتمع فاسد \nشرب الخمر ده كان بالنسبة لهم زي شرب المية عندنا، التعامل بالربا ده حاجة أساسية في حياتهم، \nالزنى بقى مقلكوش \nكان في خِيام كده معمولة وعليها زي رايات...يعني علامات معروفة إن دي خيام البغايا ومعروفة في التاريخ باسم الرايات الحُمر للي عايز يروح يزني، وكان كله عيني عينك كده\nده حتى الزواج كان داخل فيه زنى تخيلوا\nيعني كان عندهم الزواج الشرعي بتاعنا إللي هو فيه مهر وفيه ولي وفيه شهود وإعلان الزواج ونوع الزواج ده أقرّه الإسلام عادي ،\nوكان معظم الناس الناس بيتزوجوا كده ورسول الله ﷺ كان زواجه من خديجة زواج شرعي وأمه وأهله كلهم زواجهم كان زواج شرعي\nكان في بقى أنواع تانية من الزواج كانت عجيبة \nأنا هقول لكم مثال واحد عشان مطولش عليكم وعشان تعرفوا حجم الفساد والضياع إللي العرب كانوا فيه قبل الإسلام ،\nوالتغيير إللي المفروض رسول الله ﷺ هيعمله والمشاكل إللي هتواجهه\nتخيلوا إن الرجل كان يقول لمراته بعد ما تطهر من الحيض روحي لفلان من أشراف مكة وساداتها واستبضعي منه...يعني تزني معه وبعدين زوجها ميقربش منها لحد ما يبان إنها حامل من الرجل ده،\nوبعد كده خلاص بقى يقرب منها عادي، كان بيعمل كده يرجو نجابة الولد يعني يكون ابنه ذكي وقوي\nوالسادة كانوا بيرحبوا جدا بالشهوات إللي زي كده\nفطبعا أكيد هيحاربوا أي أحد ييجي يقول لهم إللي إنتم بتعملوه ده غلط أو في دين بيقول لكم إن الكلام ده ممنوع\nمتسألوش بقي في المواقف دي فين غيرة الرجل العربي إللي كان ممكن يذبح فرس بسبب إن مراته قعدت عليه عشان ميجيش راجل تاني يقعد عليه مكانها\nولا تسألوا عن مشاعر المرأة وهي رايحة لواحد يعاشرها بأمر من زوجها ومفيش حاجة اسمها إنها تعترض وتقول لأ\nهي كانت مجرد أداة تسمع وتطيع، ولا تسألوا عن اختلاط الأنساب وضياع الحقوق \nدي حاجة بسيطة من وضع البلد إللي رسول الله ﷺ نشأ وتربى فيها ،\nوالمفروض إنه هيغير الحاجات دي كلها، وأهل مكة مكنوش عايشين عالفساد والكفر ده سنة ولا اتنين،\nولا عشرة ولا عشرين ده كانوا عايشين عليه مئات السنين أجيال ورا أجيال\nيعني الحاجات دي مغروسة فيهم...شاربينها كده وبتجري في دمهم\nفإزاي رسول الله ﷺ هيغير الكلام ده وهو بشر زيهم \nكل واحد فينا يحاول يربط بين الواقع بتاعه وظروفه إللي هو عايش فيها،\nوالظروف إللي رسول الله ﷺ كان عايش فيها أيهما أصعب وأشد\nهنطلع من مكة دلوقتي ونشوف العالم المحيط بمكة في الوقت ده كان عامل إزاي\nفي الزمن ده كان في دولتين بيحكموا الأرض، \nالدولة الرومانية كانت بتحكم نصف الأرض، والدولة الفارسية كانت بتحكم النصف الثاني،\nوكانوا على طول هم الإثنين بيتخانقوا مع بعض عشان يثبتوا مين الأقوى\nزي أمريكا والاتحاد السوفييتي زمان قبل ما ينحل وتبقى روسيا دلوقتي هي إللي القائدة للنزاع،\nوكل واحد منهم عايز يثبت للتاني إنه أقوى ونفوذه أكبر\nفتخيل نفسك كده مكان رسول الله ﷺ إنت تكون إيه بالنسبة لدولتين كُبار زي أمريكا وروسيا\nأهه ده بالضبط كان وضع رسول الله ﷺ لما ربنا بعثه عشان يدعو أهل الأرض ومنهم الفرس والروم\nإللي هو بالمقياس البشري حاجة مستحيلة محدش يقدر يتجرأ إنه يفكر فيها بس\nوالروم دول كان طبعهم وحْشِي كانوا بيرموا العبيد للحيوانات يتصارعوا معاها وهم بيتفرجوا عليهم \nفالعبيد بالنسبة لهم مكنش لهم أي حقوق أصلا،\nمع إن العبيد في الدولة الرومانية كانوا ثلاثة أضعاف الأحرار، حتى أفلاطون الفيلسوف المعروف صاحب فكرة المدينة الفاضلة[اليوتوبيا] إللي كان بيتخيلها في عقله كان بيقول : \nإنه لا يجب أن يُعطى العبيد حق المواطنة \nمع إنهم من أهل البلد ..بس ملهمش قيمة عند الرومان\n☆خليكوا فاكرين معاملة العبيد كانت عاملة إزاي عشان تشوفوا الإسلام عمل إيه مع العبيد\nنسيب الرومان ونشوف الفرس \nودول كانوا حاجة كده فوق الوصف كانوا بيعملوا حاجة كل أهل الأرض كانوا بينفروا منها وكانوا بيعيبوا على أهل فارس الموضوع ده\nكان عندهم زواج المحارم ده حاجة عادية جدا \nالرجل يتزوج أمه.. أخته...بنته...عادي جدا والموضوع كان منتشر بين السادة وبين عوام الناس\nوكان الناس بتقدّس الأكاسرة يعني ملوك الفرس وكان منتشر بينهم إن الأكاسرة دول في دمهم دم الإله، \nلدرجة إن الناس المقربين من كسرى مكنوش يقفوا قصاده أو جنبه،\n لازم يكونوا بعيد عنه أمتار وإللي عايز يدخل على كسرى لازم يحط على وشه قماشة زي نقاب كده عشان أنفاسه لا تلوث الحَضرة الملكية\nنروح لأوروبا كانوا في قمة التخلف والحروب بينهم مستمرة،\nمصر كان بيحكمها الرومان وكان فارضين على الشعب الضرائب الباهظة على كل حاجة لدرجة إنهم فرضوا ضريبة على إللي يموت \nوالظلم منتشر والاضطهاد والتعذيب\nالهند بقى كانت العجب العجاب كانوا بيعبدوا كل حاجة لدرجة إنهم عبدوا أدوات الكتابة القلم والكراسة وعبدوا الفئران\nوالصين كانوا كفار عندهم ثلاثة ديانات منهم عبادة بوذا ،\n☆شوفوا مهما تتخيلوا مش هتقدروا تتصوروا أوضاع الأرض في زمن بعثة رسول الله ﷺ كانت عاملة إزاي\nتخيلوا إن رسول الله ﷺ بيقول عن ربنا في حديث قدسي :\n\" إِنَّ اللَّهَ نَظَرَ إِلَى أَهْلِ الْأَرْضِ فَمَقَتَهُمْ عَرَبَهُمْ وَعَجَمَهُمْ إِلا بَقَايَا مِنْ أَهْلِ الْكِتَابِ\"\nالمقت يعني شدة الكره، فربنا كره البشر من كثرة الفساد في الأرض إلا ناس قليلة جدا من أهل الكتاب إللي استمروا متمسكين بدينهم الصحيح\nفكانت الأرض في الزمن ده محتاجة حد يرشدها للطريق الصحيح.\nحاولوا تقارنوا بين الوضع في زمن الجاهلية وحال الأرض دلوقتي سواء في بلاد المسلمين أو حتى في أي دولة من دول العالم ،\nهتلاقوا إن في تشابه كبير جدا بينهم،\nالزنا وقتل الأطفال والظلم والإلحاد والشرك والقتل والتعذيب والإغتصاب ..كل ده بقى منتشر في زماننا \nفالعالم دلوقتي محتاج الإسلام مرة ثانية\nفي المرة الأولى كان محمد رسول الله ﷺ ، والدور علينا دلوقتي إننا نتبع نفس خطوات رسول الله ﷺ عشان ننشر الإسلام ونبني أمة الإسلام مرة ثانية ،\nخلونا نشوف المنهج والخطوات التي بدأها رسول الله ﷺ \nرسول الله ﷺ فهم دلوقتي تفسير الحاجات الغريبة إللي كانت بتحصل له، \nزي إللي كان بيسلم عليه وهو ماشي وكان بيقول السلام عليك يا رسول الله.. عرف إن ده كان الحجر والشجر\nأول خطوة عملها رسول الله ﷺ عشان يوصل دعوته هو إختيار الأشخاص المناسبين عشان يكلمهم في أمر الإسلام\nماهو مينفعش أي حد كده يروح يقو له أنا رسول \nاحنا عايزين نحط أساس متين نقدر نبني عليه وعايزين إللي يصدقنا، ويساعدنا مش إللي يقول لك يا شيخة إيه التشدد ده، ولّا إنت اتجننت ولا إيه ..ولّا إللي يقعد يسخر منك\nفهو دوّر على الناس إللي بيثق فيهم وعارف إنه لو قال لهم إنه رسول هيصدقوه وكمان يساعدوه ويقفوا جنبه \nومش بس كده ده أنا لازم أكون عارف إن الشخص إللي أنا هدعوه ده بيحبني وبيثق فيّ، ماهو أنا ممكن أكون بثق في أحد وبحبه وهو مش بيبادلني نفس المشاعر وممكن يكون بيكرهني أصلا \nفأنا ممكن يكون كلامي صحيح ومقنع بس عشان الشخص إللي انا بدعوه به بيكرهني فمش هيسمع كلامي\nفأول قاعدة في الدعوة هي إن يكون معاك الكلام المقنع وفي نفس الوقت تحببي الناس فيك\nوالناس هتحبك لما تكون أخلاقك ومعاملاتك زي أخلاق رسول الله ﷺ؛\n لأن أكثر حاجة ممكن تجذب الإنسان في الشخص إللي قصاده هو حسن الخلق\nوحسن الخلق بكل بساطة هو وجه بشوش بيضحك ،\nمع كلام طيب جميل،\nمفهوش شتيمة ولا احتقار ..وكمان إنك تحسس إللي قصادك إنك خايف عليه مش مجرد تقوله حلال وحرام وخلاص\nوطبعا مش هتقدر توصّل للناس الإحساس ده غير لما تكون فعلا من قلبك حاسه\n لأن إللي في القلب بيوصل للقلب وهو ده إللي كان بيعمله رسول الله ﷺ\nمين بقى الأشخاص إللي ينطبق عليهم الكلام إللي احنا قلناه ده في حياة رسول الله ﷺ \nأول واحدة كانت زوجته ورفيقة عمره وأم أولاده وإللي كانت دايما بتعينه على فعل الخير خديجة بنت خويلد \n فراح قال لها إن هو رسول من رب العالمين أرسله للناس عشان يدعوهم لعبادة الله وحده ،\nوإنهم يتركوا عبادة الأصنام فآمنت خديجة على طول\n ماهي متابعة الموضوع من البداية\nوأكثر واحدة تعرف الرجل هي زوجته لأنها أكثر واحدة قريبة منه وعارفة مميزاته وعيوبه وعارفة صدقه أو كذبه\nوبعدين رسول الله ﷺ دعا ثلاثة أشخاص آخرين هم : 《عبد الله بن عثمان أو عبد الله بن أبي قحافة أو خلونا نقول : أبو بكر الصديق》\nالثاني :《علي بن أبي طالب》 ،\nوالثالث : 《زيد بن حارثة》\nرسول الله ﷺ دعاهم للإسلام، \nمين هم الثلاثة دول وهل فعلا أسلموا زي خديجة ولّا إيه كانت رد فعلهم؟\nواشمعنى العرب بالذات إللي ربنا اختارهم عشان تكون فيهم رسالة الإسلام؟\n ده إللي هنعرفه الجزء الجاي إن شاء الله \n☆باقي القصص هنا"}]);
